window.WIKI={"version":"2026-11-03","cats":[{"id":"hospital","name":"병원비보험","g":"PRODUCT","desc":"치료비와 진단비로 의료비 부담을 덜어주는 보장. 실손부터 3대진단비, 수술비까지.","children":[{"id":"silson","name":"실손의료비","items":["일반실손 · 유병자실손 · 노후실손","보상조건: 입원/통원, 상해/질병 면책사항","유지조건: 갱신·재가입 조건과 전환실손","가입시기별 조건 차이","국민건강보험과 상품의 구조"]},{"id":"diag","name":"3대진단비","items":["암: 일반암과 소액암(갑상선·경계성·제자리 등)","고액암(3대·5대·10대·16대 고액암 등)","재진단암과 이차암","암수술비와 암입원일당","뇌질환: 뇌혈관질환 · 뇌졸중 · 뇌출혈 · 뇌경색","심장질환: 허혈성심장질환"]},{"id":"disab","name":"후유장해","items":["질병후유장해","상해후유장해","장해분류표 읽는 법"]},{"id":"liab","name":"배상책임","items":["자녀 · 일상 · 가족 일상생활배상책임","배상책임 보상 사례"]},{"id":"driver","name":"운전자보험","items":["교통사고처리지원금(형사합의금)","벌금","변호사선임비용","교통사고 부상치료비"]},{"id":"surg","name":"수술비","items":["수술의 정의와 사례","생명보험 종수술비와 손해보험 특정수술비"]},{"id":"hosp-etc","name":"입원일당 · 기타","items":["입원일당","기타 병원비 담보"]}]},{"id":"death","name":"사망보험","g":"PRODUCT","desc":"가장의 부재에 대비하는 보장. 종신과 정기의 구조, 사망 원인별 보장 차이.","children":[{"id":"whole","name":"종신보험","items":["종신보험의 구조","CI보험과 GI보험","\"중대한\"의 의미와 컨셉","납입면제 · 추가납입 · 중도인출 · 납입정지 · 연금전환"]},{"id":"termlife","name":"정기보험","items":["정기보험의 구조와 활용"]},{"id":"accdeath","name":"재해사망과 상해사망","items":["재해사망과 상해사망의 차이","상해의 입증요소: 외래성 · 우연성 · 급격성"]},{"id":"disdeath","name":"질병사망과 일반사망","items":["질병사망과 일반사망의 차이","사망의 원인과 확률, 보장범위"]}]},{"id":"annuity","name":"저축·연금보험","g":"PRODUCT","desc":"노후와 목돈을 준비하는 상품. 공시이율형과 변액형, 세제 조건.","children":[{"id":"fixed","name":"공시이율형 상품","items":["연금저축: 세액공제의 개념과 장단점","연금펀드","연금보험","저축보험","종신보험을 이용한 저축플랜"]},{"id":"variable","name":"변액투자형 상품","items":["변액유니버셜 저축보험(VUL)","변액연금보험(VA)","변액상품의 펀드 개념과 관리 방법"]},{"id":"taxfree","name":"비과세와 상품 비교","items":["비과세 및 비과세 조건","상품 기능별 차이점"]}]},{"id":"fire","name":"화재보험","g":"PRODUCT","desc":"주택과 사업장의 재산 손해를 보장하는 상품의 구조와 담보.","children":[{"id":"fire-basic","name":"화재보험의 구조와 종류","items":["화재보험의 의의","화재보험의 구조 및 종류"]},{"id":"fire-cover","name":"화재보험 담보구성","items":["화재보험의 담보 구성"]}]},{"id":"auto","name":"자동차보험","g":"PRODUCT","desc":"대인·대물부터 자기신체사고와 자동차상해의 차이까지.","children":[{"id":"auto-cover","name":"대인 · 대물 · 자손/자상","items":["대인배상","대물배상","자기신체사고와 자동차상해의 차이"]},{"id":"auto-terms","name":"자동차보험 약관과 특약","items":["자동차보험 약관","추가 가능한 특약과 가입 팁"]}]},{"id":"terms","name":"약관","g":"RULES","desc":"보험계약의 규칙. 상법과 보험업법, 보통약관, 분쟁사례.","children":[{"id":"law","name":"상법과 보험업법","items":["상법 보험편과 보험업법의 역할"]},{"id":"general","name":"보통약관","items":["부담보","실효와 부활","납입면제","청약철회","계약 전 알릴 의무"]},{"id":"special","name":"특별약관","items":["특별약관의 구조"]},{"id":"dispute","name":"분쟁사례와 판례","items":["분쟁사례 및 판례 정리"]}]},{"id":"goji","name":"고지의무·보상","g":"RULES","desc":"계약 전 알릴 의무와 보험금 청구. 인수와 보상을 가르는 지점.","children":[{"id":"disclosure","name":"고지의무 (일반 · 간편)","sample":true,"items":["계약 전 알릴 의무란","일반심사 고지 항목","간편고지(3·2·5)","위반 시 처리와 해지 제한","실무 체크포인트"]},{"id":"claim","name":"보험금 청구 절차","items":["보험금 청구 및 절차","고지의무 적용 방법과 보상"]},{"id":"benef","name":"수익자 지정","items":["수익자 지정 및 케이스"]}]},{"id":"basics","name":"상품 기초개념","g":"RULES","desc":"설계 전에 반드시 구분해야 할 상품 구조와 용어.","children":[{"id":"renew","name":"갱신형과 비갱신형","items":["갱신형과 비갱신형의 구조","보험료 비교 시 주의점"]},{"id":"refund","name":"환급형과 순수보장형","items":["환급형과 순수보장형","적립보험료의 의미"]},{"id":"maturity","name":"80세 만기와 100세 만기","items":["만기 선택 기준"]},{"id":"nonrefund","name":"납입기간과 무해지상품","items":["납입기간 설정","무해지환급형 상품의 구조"]},{"id":"disease","name":"주요 질병과 인수기준","items":["주요 질병의 원인 · 통계 · 치료법","질병별 인수기준"]}]},{"id":"channel","name":"판매채널·영업","g":"SALES","desc":"원수사와 GA의 구조, 대면영업과 비대면영업 방식.","children":[{"id":"ga","name":"원수사와 GA","items":["원수사","대리점(GA): 연합형과 독립형","영업규정 · 수수료 · 근무환경"]},{"id":"offline","name":"대면영업","items":["지인 · DB · 브리핑 · 개척 · 법인영업","재무설계: 수입/지출 · 상품관리","금융기초: 은행 · 증권사 · 보험사","정보받기 → 재무목표 설정 → 상품제안"]},{"id":"online","name":"비대면영업","items":["카페 · 댓글 · 광고 · SNS · 블로그","블로그 포스팅 기본 양식과 상위노출 로직","블로그 컨셉 잡기와 로열키워드","검색량 · 포스팅 수 · 제한키워드 · 노출기준 확인","유튜브 · 네이버TV · SNS 마케팅"]}]},{"id":"sales","name":"세일즈 프로세스","g":"SALES","desc":"가망고객 발굴부터 소개까지, 계약이 만들어지는 8단계.","route":"sales","children":[{"id":"step-1","name":"1. 가망고객 확보","step":1},{"id":"step-2","name":"2. 접근","step":2},{"id":"step-3","name":"3. 니즈 환기","step":3},{"id":"step-4","name":"4. 정보 수집","step":4},{"id":"step-5","name":"5. 제안","step":5},{"id":"step-6","name":"6. 클로징","step":6},{"id":"step-7","name":"7. 계약 및 사후관리","step":7},{"id":"step-8","name":"8. 소개 & 스케줄 관리","step":8}]}],"steps":[{"n":1,"k":"Prospecting","name":"가망고객 확보","short":"가망고객","quote":"연락이 닿지 않는 사람은 고객이 아니다.","intro":"좋은 가망고객은 세 가지 조건을 갖춰야 합니다.","checks":[["연락 가능성","전화나 톡이 가능한가. 연락조차 안 되면 가망고객이 아닙니다."],["니즈","보험에 대한 필요성이 있는가. 니즈가 전혀 없다면 상담 난이도가 높아집니다."],["신뢰도","나를 믿거나 관계가 있는가. 자발적 소개나 기존 신뢰 관계가 있는 고객이 가장 좋습니다."]],"tip":"지인 영업만 고집하지 마세요. 온라인영업, DB영업, 기존 고객 관리로 가망고객을 계속 업데이트하는 것이 롱런의 비결입니다.","scripts":[]},{"n":2,"k":"Approach · AP","name":"접근","short":"AP","quote":"첫인상이 영업의 절반이다.","intro":"AP의 목적은 신뢰도 높이기와 분위기 전환, 두 가지입니다. 고객은 설계사라는 직업 자체에 대한 신뢰가 낮습니다. 보험 이야기 전에 고객을 위해 일하는 전문가라는 점부터 보여주세요.","checks":[["신뢰 안내","첫 인사에서 명함 전달, 상담 절차와 기준 안내로 신뢰를 주고 있는가"],["분위기 전환","칭찬, 공통 관심사, 아이스브레이킹으로 관계를 풀었는가"]],"tip":"자신만의 레퍼토리를 만드세요. 사투리도 훌륭한 무기가 됩니다.","scripts":[]},{"n":3,"k":"Needs","name":"니즈 환기","short":"니즈환기","quote":"고객이 스스로 필요하다고 느끼게 만들어라.","intro":"대부분의 고객은 보험 니즈가 크지 않습니다. 감성에 기대기보다 객관적이고 예측 가능한 사례로 설명하세요. 보험 목적 카테고리와 질병 관련 니즈를 활용하면 효과적입니다.","checks":[["보장공백 안내","카테고리별로 현재 보험의 공백을 짚어주었는가"],["맞춤형 질병 리스크","병력과 가족력을 확인해 막연한 불안을 구체적인 질병 리스크로 설명했는가"]],"tip":"감정보다 근거. 통계와 가족력처럼 고객이 직접 확인할 수 있는 사실로 이야기하세요.","scripts":[]},{"n":4,"k":"Fact Finding · FF","name":"정보 수집","short":"FF","quote":"아는 만큼 설계하고 제안할 수 있다.","intro":"FF는 서류 작성이 아니라 고객에게 닥칠 미래의 위험을 예측하는 과정입니다. 병력과 가족력을 파악하면 막연한 걱정이 특정 질병으로 구체화되고, 설계의 명분이 생깁니다.","checks":[["의학적 상담의 관점","병력·가족력 질문이 위험 예측 과정임을 고객이 이해하고 있는가"],["가족 단위로 확장","배우자, 자녀, 부모님까지 가족 단위 보장 분석으로 상담 규모를 키웠는가"],["기존 보험에 대한 태도","\"지금 보험에 만족하시나요?\"로 숨은 불만과 미충족 니즈를 찾았는가"]],"tip":"건강검진의 추적 관찰·주의 판정 항목은 그 자체로 상담의 중심 포인트가 됩니다.","scripts":[]},{"n":5,"k":"Presentation · PT","name":"제안","short":"PT","quote":"설명은 심플하게, 선택은 확실하게.","intro":"여러 안을 늘어놓아 고객을 혼란스럽게 하지 마세요. 검토를 끝낸 최선의 단일안을 추천하는 것이 기본입니다. 고객이 망설일 때만 기준점이 되는 비교안을 꺼냅니다.","checks":[["선비교 후제안","수치와 회사별 특징을 언급해 이미 비교 검토가 끝났음을 보여주었는가"],["단일안의 근거","FF에서 확인한 가족력·병력·보장공백과 설계를 연결했는가"],["대조 효과","망설일 때 비교안을 보여 추천안을 선택할 이유를 다시 확인시켰는가"]],"tip":"\"이게 추천견적입니다\"보다 \"왜 고객님께 맞는지\"를 먼저 말하세요.","scripts":[]},{"n":6,"k":"Closing · CL","name":"클로징","short":"클로징","quote":"계약은 강요가 아니라 확인하는 과정이다.","intro":"앞선 과정(AP·니즈·FF·PT)이 단단했다면 계약은 자연스러운 결과입니다. 마지막에 고객이 망설인다면 클로징 기술보다 앞 단계 어딘가에 구멍이 있다는 신호입니다.","checks":[["이해 확인","고객이 보장 범위와 제외 조건을 자신의 말로 설명할 수 있는지 확인합니다."],["조건 확인","보험료 납입, 고지 답변, 보장개시 조건을 함께 점검합니다."],["가입 의사","설명을 충분히 듣고 고객 본인의 의사로 결정하는지 확인합니다."]],"diag":true,"tip":"\"그래서 하실 건가요? 선물 잘 챙겨드릴게요.\" 같은 질문형 클로징은 피하세요.","scripts":[]},{"n":7,"k":"Management","name":"계약 및 사후관리","short":"사후관리","quote":"계약은 끝이 아니라 소개와 업셀링을 향한 시작이다.","intro":"계약은 고객이 나를 전문가로 인정했다는 증거입니다. 이때부터의 관리가 설계사의 연봉을 결정합니다. 잘 관리된 고객 한 명은 수십 명의 잠재 고객을 데려오는 마케팅 채널이 됩니다.","checks":[["소개의 선순환","신규 개척보다 관리를 통한 소개가 계약 성사율이 높습니다"],["업셀링의 기회","결혼·출산·승진 같은 생애주기 추가 설계는 신뢰가 쌓인 뒤에만 가능합니다"],["전문가의 증명","보험의 가치는 보상받는 순간 결정됩니다. 그때 곁에 있는 설계사가 진짜 전문가입니다"]],"tip":"계약 직후 첫 연락 일정을 바로 캘린더에 잡아두세요.","scripts":[]},{"n":8,"k":"Referral","name":"소개 & 스케줄 관리","short":"소개","quote":"소개는 부탁하는 게 아니라 자발적으로 나오는 것이다.","intro":"전문가로서 자리를 지키고 꾸준히 유익한 정보를 주면 소개는 자연스럽게 나옵니다. 이 선순환이 완성되면 영업은 거절이 두려운 일이 아니라 정답을 알려주는 일이 됩니다.","checks":[["구글 캘린더","지난 일이 아니라 앞으로의 고객관리 일정을 기록하세요"],["자료 보관","고객 자료는 비공개 공간에 체계적으로 저장하고, 개인정보 보호 기준을 지키세요"]],"tip":"세일즈 프로세스는 계약 기술이 아니라 전문가의 로드맵입니다.","scripts":[]}],"gloss":[["goji","고지의무 (계약 전 알릴 의무)","청약할 때 보험회사가 질문한 중요한 사항을 사실대로 알려야 하는 의무. 위반하면 계약이 해지되거나 보험금이 지급되지 않을 수 있습니다."],["simple","간편고지","보험회사가 정한 질문으로 건강 상태를 확인하는 심사 방식입니다. 질문이 짧아도 빠짐없이 답해야 하며 질문 기간과 인수 조건은 가입시기·상품에 따라 다릅니다."],["bojang","보장개시일","보험회사의 보장 책임이 시작되는 날. 암 보장처럼 별도의 대기기간이 있는 담보도 있습니다."],["renew","갱신형","정해진 주기에 계약을 갱신하며 보험료를 다시 산정하는 구조입니다. 나이와 위험률 등의 변화로 보험료가 달라질 수 있습니다. 갱신 주기와 종료 조건은 가입시기·상품에 따라 다릅니다."],["nonrenew","비갱신형","정한 납입기간 동안 약정된 보험료를 내는 구조입니다. 주계약과 특약의 갱신 여부를 각각 확인하며, 계약 변경에 따른 보험료 변동은 별도로 살펴봅니다."],["nonrefund","무해지환급형","정해진 기간에 해지하면 해지환급금이 없거나 적게 설계된 구조입니다. 납입이 끝난 뒤의 환급 방식도 가입시기·상품에 따라 다릅니다."],["silson","실손의료비","실제 부담한 의료비를 약관 기준에 따라 보상하는 보험. 가입 시기에 따라 자기부담금과 보상 조건이 다릅니다."],["napmyeon","납입면제","약관에서 정한 사유가 생기면 이후 보험료를 내지 않아도 보장이 유지되는 기능."],["budambo","부담보","특정 부위나 질병을 일정 기간 또는 전 기간 보장에서 빼고 인수하는 조건."],["silhyo","실효","보험료가 연체되고 정해진 납입최고 절차를 거쳐 계약의 효력이 끝난 상태를 뜻합니다. 자동이체 실패만으로 즉시 실효된 것으로 단정하지 말고 계약 상태를 확인합니다."],["buhwal","부활","보험료 연체로 해지된 계약을 정해진 요건에 따라 다시 유지하는 절차입니다. 신청 기간, 미납 보험료 납입, 고지와 심사 조건은 가입시기·상품에 따라 다릅니다."],["cheolhoe","청약철회","가입 후 정해진 기간과 요건 안에서 청약 의사를 거두는 제도입니다. 적용 대상과 예외, 기간의 계산 기준은 계약 서류로 확인합니다. 단순 해지와 구별해야 합니다."],["wonsu","원수사","보험상품을 직접 만들고 보험금을 지급하는 보험회사."],["GA","GA (법인보험대리점)","여러 보험회사의 계약 체결을 대리하는 법인보험대리점입니다. 상품을 만드는 보험회사와 판매를 대리하는 조직의 역할을 구분하며 실제 취급 범위는 제휴 관계에 따라 다릅니다."],["AP","AP (Approach)","세일즈 2단계. 신뢰를 만들고 분위기를 전환하는 접근 단계."],["FF","FF (Fact Finding)","세일즈 4단계. 병력·가족력·기존 보험·예산을 파악하는 정보 수집 단계."],["PT","PT (Presentation)","세일즈 5단계. 검토를 끝낸 설계안을 제안하는 단계."],["CL","CL (Closing)","세일즈 6단계. 앞선 과정을 확인하며 계약으로 마무리하는 단계."]],"items":[{"id":"silson-0","cat":"hospital","cat_name":"병원비보험","doc":"silson","doc_name":"실손의료비","index":0,"title":"일반실손 · 유병자실손 · 노후실손","definition":"실손의료비는 실제 부담한 치료비 중 계약에서 정한 비용을 보상하며, 가입 대상에 따라 심사와 보장 구성이 달라집니다.","explanation":["일반실손은 통상적인 건강 심사를 거쳐 가입하는 형태입니다. 유병자실손은 치료 이력이 있는 사람의 가입 가능성을 넓히도록 심사 항목을 줄인 형태이지만, 병력이 있다는 이유만으로 모두 가입할 수 있는 것은 아닙니다.","심사가 간소하다는 점과 보장이 넓다는 점은 별개입니다. 유병자실손에는 처방조제나 일부 비급여 치료가 제외되는 구조가 있으므로, 일반실손과 동일한 보장이라고 설명해서는 안 됩니다.","노후실손은 고령층의 의료비 부담에 대응하는 구조입니다. 요양병원 의료비나 상급병실료 차액을 별도 특약으로 나누는 경우가 있어 기본계약에 포함되는지 확인해야 합니다.","가입 연령, 보장 종료 시점, 자기부담금과 공제 방식은 가입시기·상품에 따라 다릅니다. 상품 유형만으로 예상 보험금이나 장기간의 보험료 부담을 단정하기 어렵습니다."],"practical":["고객이 주로 받는 진료가 외래인지, 처방약 복용인지, 입원인지 먼저 파악한 뒤 실제 가입 가능한 보장 항목과 대조합니다.","병력이 있어도 일반실손 심사 가능 여부와 유병자실손의 제외 항목을 함께 확인하고, 계약별 차이를 고객이 이해하도록 설명합니다."],"faq":[],"path":"articles/silson/01/"},{"id":"silson-1","cat":"hospital","cat_name":"병원비보험","doc":"silson","doc_name":"실손의료비","index":1,"title":"보상조건: 입원/통원, 상해/질병 면책사항","definition":"실손의 보상조건은 치료 원인과 진료 형태, 비용 구분을 각각 따져 지급 대상을 정하는 기준입니다.","explanation":["상해와 질병, 입원과 통원은 계약상 서로 다른 보장종목이나 계산 기준으로 나뉠 수 있습니다. 같은 병원에서 지출한 비용이라도 어느 항목에 해당하는지 먼저 확인해야 공제와 한도를 적용할 수 있습니다.","급여 본인부담금과 비급여 의료비를 구분하는 구조에서는 각각 자기부담금이 적용될 수 있습니다. 영수증의 총액만 보고 공제액을 한 번만 빼거나 전액을 받을 것으로 예상하면 실제 지급액과 차이가 생깁니다.","치료 목적으로 발생한 비용이어도 계약에서 보상하지 않는 항목에 해당하면 지급되지 않을 수 있습니다. 한방 비급여나 특정 비급여 치료, 처방조제의 취급은 가입한 실손의 유형과 약관을 확인합니다.","입원·통원의 한도와 횟수, 비용별 공제 방식은 가입시기·상품에 따라 다릅니다. 병원의 진료 분류와 실제 치료 내용, 계약의 보장종목을 함께 살펴보는 것이 청구 검토의 출발점입니다."],"practical":["진료비 영수증과 세부내역에서 급여·비급여 및 진료 항목을 확인하고, 계약의 제외 항목에 해당하는 부분을 따로 표시합니다.","고객에게는 예상 지급액을 확정금액처럼 말하지 말고, 실제 내역과 공제 기준을 확인한 뒤 지급 심사가 이루어진다고 설명합니다."],"faq":[],"path":"articles/silson/02/"},{"id":"silson-2","cat":"hospital","cat_name":"병원비보험","doc":"silson","doc_name":"실손의료비","index":2,"title":"유지조건: 갱신·재가입 조건과 전환실손","definition":"갱신은 계약을 정해진 주기로 이어 가는 절차이고, 재가입과 전환은 보장 내용이 바뀔 수 있는 별도의 절차입니다.","explanation":["보험료 변경주기와 보장내용 변경주기는 같은 개념이 아닙니다. 갱신 시 보험료가 바뀌는 것과 재가입 때 면책사항·보상한도 등이 바뀌는 것을 나누어 안내해야 유지 계획을 세울 수 있습니다.","재가입 대상 계약은 만기 시점에 적용되는 보장 내용과 절차를 확인해야 합니다. 재가입 의사 확인, 안내 방법, 의사 표시가 없는 경우의 처리 방식은 계약에 따라 정해집니다.","전환을 검토할 때는 보험료 변화와 함께 급여·비급여 보장, 자기부담금, 제외 항목을 비교합니다. 할인만 보고 결정하면 평소 이용하는 진료에 대한 실제 부담이 늘어나는 부분을 놓칠 수 있습니다.","갱신·재가입 주기와 전환 가능 조건은 가입시기·상품에 따라 다릅니다. 전환 뒤 취소나 원계약 복원이 가능한지 역시 해당 절차의 요건을 따로 확인해야 합니다."],"practical":["증권에 적힌 만기와 보험료 변경주기, 재가입 시점을 각각 기록하고 도래 전에 고객에게 필요한 확인사항을 안내합니다.","전환 전후를 같은 진료 상황으로 비교하되 실제 계약에 적용되는 조건을 사용하고, 동의 내용과 변경되는 항목을 남깁니다."],"faq":[],"path":"articles/silson/03/"},{"id":"silson-3","cat":"hospital","cat_name":"병원비보험","doc":"silson","doc_name":"실손의료비","index":3,"title":"가입시기별 조건 차이","definition":"실손의 가입시기는 보장 범위와 공제 방식, 계약을 이어 가는 조건을 확인하는 중요한 기준입니다.","explanation":["실손이라는 같은 이름을 사용해도 모든 계약의 구조가 같지는 않습니다. 급여와 비급여를 구분하는 방식, 별도 특약의 구성, 보험료 할인 조건 등에 차이가 있으므로 현재 판매 기준을 과거 계약에 그대로 대입하지 않습니다.","보험료가 바뀌는 주기와 보장 내용이 바뀔 수 있는 주기도 구분해야 합니다. 재가입 조건이 없는 계약과 정해진 보장내용 변경주기에 재가입하는 계약은 유지 과정에서 확인할 내용이 다릅니다.","전환을 한 이력이 있다면 최초 가입 시점만으로 현재 보장을 판단할 수 없습니다. 현재 유효한 계약과 특약, 전환 이후의 자기부담금 및 보장 제외 항목을 기준으로 살펴봅니다.","보장 한도나 통원 공제액은 가입시기·상품에 따라 다릅니다. 오래된 계약이 언제나 유리하거나 새 계약이 언제나 저렴하게 유지된다고 단정하지 말고 고객의 진료 이용과 보험료 부담을 함께 봅니다."],"practical":["고객이 기억하는 가입연도만 듣고 판단하지 말고 현재 증권과 계약 변경 내역을 확인합니다.","상담표에는 입원·통원, 급여·비급여, 특약, 갱신·재가입 조건을 같은 순서로 적어 서로 다른 계약도 비교하기 쉽게 만듭니다."],"faq":[],"path":"articles/silson/04/"},{"id":"silson-4","cat":"hospital","cat_name":"병원비보험","doc":"silson","doc_name":"실손의료비","index":4,"title":"국민건강보험과 상품의 구조","definition":"국민건강보험의 급여 구분은 실손의료비가 어떤 치료비를 어떤 방식으로 보상하는지 살피는 기초입니다.","explanation":["진료비 영수증에서는 급여 부분과 비급여 부분을 나누어 확인합니다. 실손은 이 구분을 바탕으로 계약이 정한 의료비를 보상하므로 총진료비와 고객이 실제 부담한 비용을 혼동하지 않아야 합니다.","급여 의료비를 기본계약으로, 비급여 의료비를 특약으로 구분하는 구조가 있습니다. 이 경우 비급여 특약의 가입 여부를 확인하지 않고 모든 비급여 치료가 보장된다고 설명하면 안 됩니다.","급여와 비급여에 각각 공제가 적용되는 계약도 있습니다. 따라서 동일한 진료에서 발생한 비용이라도 보험금 계산 과정에서 서로 나누어 판단될 수 있습니다.","건강보험 급여가 아니라고 해서 실손이 모두 보상하는 것은 아닙니다. 비급여 중에도 제외 항목이 있고 상품 유형에 따라 처방조제나 특정 치료의 취급이 달라집니다. 구체적인 보장 내용은 가입시기·상품에 따라 다릅니다."],"practical":["고객에게 영수증의 급여·비급여 칸과 실제 납부액을 함께 보여 주며 보장 판단의 순서를 설명합니다.","비급여 치료를 문의받으면 먼저 가입 특약과 해당 치료의 제외 여부를 확인하고, 단순히 비급여라는 이유로 지급을 약속하지 않습니다."],"faq":[],"path":"articles/silson/05/"},{"id":"diag-0","cat":"hospital","cat_name":"병원비보험","doc":"diag","doc_name":"3대진단비","index":0,"title":"암: 일반암과 소액암(갑상선·경계성·제자리 등)","definition":"암 진단비는 보장개시일 등 계약 요건을 충족한 뒤 정해진 암으로 진단이 확정되면 약정한 금액을 지급하는 보장입니다.","explanation":["보험에서 말하는 일반암과 소액암의 범위는 일상적인 병의 심각도 구분과 같지 않습니다. 갑상선암이나 기타피부암을 별도로 정하거나 제자리암·경계성종양을 구분하는 계약이 있으므로 해당 질병 분류를 확인합니다.","제자리암은 계약이 정한 제자리신생물에 해당하는지, 경계성종양은 행동양식이 불명확하거나 미상인 신생물 분류에 해당하는지를 살핍니다. 이름이 비슷하다는 이유로 일반암 진단비를 바로 적용하지 않습니다.","진단확정은 조직검사 등 정해진 검사와 전문의 판단을 기초로 합니다. 병리검사가 불가능한 경우의 예외와 필요한 기록도 약관에 정해져 있어 진단서의 병명만으로 결론 내리지 않습니다.","별도로 분류되는 암의 지급금액과 보장 시작 시점은 가입시기·상품에 따라 다릅니다. 전이가 확인된 경우에도 원발부위에 관한 분류 조항이 적용될 수 있으므로 최초 발생 부위를 함께 확인합니다."],"practical":["가입한 진단비 담보별로 일반암에서 제외하는 질병과 별도 지급 항목을 나란히 정리해 보장 공백을 설명합니다.","청구 안내 시 진단서와 병리검사 결과의 진단명·확정 시점을 확인하고, 보장개시일과 대조합니다."],"faq":[],"path":"articles/diag/01/"},{"id":"diag-1","cat":"hospital","cat_name":"병원비보험","doc":"diag","doc_name":"3대진단비","index":1,"title":"고액암(3대·5대·10대·16대 고액암 등)","definition":"고액암은 치료비가 많이 들었다는 사후 판단이 아니라 계약에서 별도로 지정한 암의 범위를 뜻합니다.","explanation":["고액암이나 특정암이라는 이름만으로 보장 질병을 확정할 수 없습니다. 계약마다 별도 분류를 두며, 고액암과 특정암을 서로 다른 묶음으로 정하는 경우도 있으므로 해당 분류표를 직접 확인합니다.","백혈병·뇌암·골수암 등을 고액암으로 정한 계약이 있지만 이를 모든 상품의 공통 목록으로 사용해서는 안 됩니다. 어떤 부위의 암인지와 계약상 분류에 해당하는지가 지급 여부를 가르는 기준입니다.","담보명에 나열된 질병 묶음의 수가 많다고 모든 암을 보장하는 것은 아닙니다. 일반암 진단비와 별도로 가입했는지, 실제 진단된 암이 그 안에 포함되는지 각각 검토해야 합니다.","보장개시일과 가입 초기의 감액 여부도 확인합니다. 고액암의 범위, 지급금액과 지급횟수는 가입시기·상품에 따라 다르므로 다른 계약의 조건을 그대로 적용하지 않습니다."],"practical":["일반암 진단비와 고액암 담보를 구분해 표시하고, 별도 보장의 대상이 되는 질병 목록을 고객과 함께 확인합니다.","고객이 특정 암을 염려한다면 담보 이름의 크기보다 그 질병이 분류표에 포함되는지부터 확인해 설명합니다."],"faq":[],"path":"articles/diag/02/"},{"id":"diag-2","cat":"hospital","cat_name":"병원비보험","doc":"diag","doc_name":"3대진단비","index":2,"title":"재진단암과 이차암","definition":"재진단암과 이차암 보장은 처음 암을 진단받은 뒤 다시 발생하거나 남아 있는 암을 계약상 요건에 따라 보장합니다.","explanation":["새로운 원발암은 기존 암과 조직의 특성이 다른 암을 뜻하며, 전이암은 암세포가 다른 장소로 퍼져 자란 경우를 말합니다. 재발암은 치료로 제거한 암이 다시 나타난 경우, 잔여암은 진단 부위에 암세포가 남아 있는 경우로 구분합니다.","재진단암 담보가 위 경우를 포함하더라도 첫 암과 후속 암의 범위를 동일하게 정하지 않을 수 있습니다. 특정 암종을 제외하거나 이전 암의 종류에 따라 후속 보장을 제한하는 조항을 확인해야 합니다.","후속 보장개시일은 최초 암 또는 직전 재진단암의 진단확정일과 연동될 수 있습니다. 진료를 다시 받았다는 사실만으로 새 지급사유가 되는 것은 아니며 정해진 경과기간과 진단 요건을 충족해야 합니다.","이차암이라는 명칭만으로 재진단암과 동일한 범위를 보장한다고 판단하지 않습니다. 보장 횟수와 경과기간, 잔여암의 포함 여부는 가입시기·상품에 따라 다릅니다."],"practical":["첫 진단부터 후속 진단까지의 날짜와 암의 종류를 시간순으로 정리한 뒤, 각 보장개시일을 따로 대조합니다.","완치 여부, 전이 또는 재발 여부, 암세포 잔존에 대한 의료기록을 확인하고 단순 추적검사와 구분합니다."],"faq":[],"path":"articles/diag/03/"},{"id":"diag-3","cat":"hospital","cat_name":"병원비보험","doc":"diag","doc_name":"3대진단비","index":3,"title":"암수술비와 암입원일당","definition":"암수술비와 암입원일당은 암 진단에 더해 계약에서 정한 수술 또는 입원 요건을 충족할 때 지급하는 보장입니다.","explanation":["암수술비는 보장하는 암을 직접 치료하기 위한 수술인지 살핍니다. 진단비를 받을 수 있는 암이라고 해도 수술비 지급은 별도 요건으로 판단하므로 진단만으로 수술비 지급이 결정되지는 않습니다.","직접적인 치료는 암을 제거하거나 증식을 억제하기 위한 치료를 중심으로 정의됩니다. 단순한 면역력 강화나 회복을 위한 요양을 모두 직접치료로 보는 것은 아니며, 약관이 인정하는 예외가 있는지도 함께 확인합니다.","암입원일당은 입원의 주된 목적과 의료기관의 범위를 살핍니다. 암 치료 중 다른 질환이나 합병증 치료를 함께 받았다면 실제 입원의 목적을 확인해야 하며 입원 사실만으로 지급을 단정하기 어렵습니다.","요양병원 입원을 별도로 다루거나 제외하는 담보도 있습니다. 보장개시일, 입원 인정일수와 지급한도, 수술 지급 방식은 가입시기·상품에 따라 다릅니다."],"practical":["입퇴원확인서 외에 치료 내용과 입원 필요성을 확인할 수 있는 기록을 살펴 주된 치료 목적을 정리합니다.","암수술·암입원·요양병원 관련 담보를 구분해 가입 여부를 확인하고, 같은 암 치료라도 적용 항목이 다를 수 있음을 설명합니다."],"faq":[],"path":"articles/diag/04/"},{"id":"diag-4","cat":"hospital","cat_name":"병원비보험","doc":"diag","doc_name":"3대진단비","index":4,"title":"뇌질환: 뇌혈관질환 · 뇌졸중 · 뇌출혈 · 뇌경색","definition":"뇌질환 진단비는 뇌혈관질환·뇌졸중·뇌출혈 등 계약이 정한 질병 범위에 따라 지급 대상을 구분합니다.","explanation":["뇌출혈과 뇌경색은 구별해야 할 진단입니다. 뇌졸중이나 뇌혈관질환이라는 더 넓은 명칭의 담보라도 실제 포함 질병은 각각의 분류표로 정하므로 이름만으로 모든 뇌질환을 보장한다고 설명하지 않습니다.","뇌혈관질환 분류에는 출혈과 경색 외에 혈관의 폐쇄·협착이나 후유증 등이 포함되는 구조가 있습니다. 반면 뇌출혈만을 보장하는 담보를 뇌경색까지 보장하는 담보처럼 안내하면 보장 공백을 놓치게 됩니다.","진단확정은 의사의 판단과 병력, 신경학적 검진, 영상검사 등 약관에서 정한 근거를 바탕으로 합니다. 검사상 이상이 보였다는 말과 보험에서 요구하는 질병의 확정은 나누어 확인합니다.","담보를 세부 질환별로 나누어 지급하거나 별도로 보장하는 계약도 있습니다. 보장 범위, 지급횟수 및 감액 조건은 가입시기·상품에 따라 다릅니다."],"practical":["기존 증권의 뇌 관련 담보를 정확한 명칭으로 정리하고 분류표의 포함 질병을 확인해 고객에게 설명합니다.","청구 시 진단서와 영상검사 결과를 함께 검토하되, 설계사가 의료 진단을 대신하거나 검사 소견만으로 지급을 약속하지 않습니다."],"faq":[],"path":"articles/diag/05/"},{"id":"diag-5","cat":"hospital","cat_name":"병원비보험","doc":"diag","doc_name":"3대진단비","index":5,"title":"심장질환: 허혈성심장질환","definition":"허혈성심장질환 진단비는 협심증과 심근경색증 등 약관의 허혈성심장질환 분류에 해당하는 질병을 보장합니다.","explanation":["허혈성심장질환은 급성심근경색증보다 넓은 질병 묶음으로 정해지는 구조입니다. 협심증, 후속 심근경색증, 만성 허혈심장병 등 포함 항목을 분류표에서 확인하면 보장 범위를 구체적으로 설명할 수 있습니다.","급성심근경색증 진단비만 가입한 경우 협심증을 같은 지급사유로 볼 수는 없습니다. 반대로 허혈성심장질환 담보가 있다고 해서 부정맥이나 모든 심장질환을 자동으로 보장하는 것도 아닙니다.","진단비와 특정치료비는 지급 계기가 다릅니다. 진단을 기준으로 지급하는 담보와 수술·혈전 관련 치료·중환자실 치료 등 추가 조건을 요구하는 담보를 구분해 확인합니다.","통합형 담보 안에서 급성심근경색증과 그 밖의 허혈성심장질환을 나누어 보장하는 경우도 있습니다. 지급횟수, 감액기간 및 적용되는 질병분류 기준은 가입시기·상품에 따라 다릅니다."],"practical":["고객에게 심장질환이라는 큰 표현만 사용하지 말고, 협심증과 급성심근경색증이 각각 어떤 담보에 들어가는지 표시합니다.","현재 증권의 진단비와 치료비를 구분하고, 질병명 외에 추가로 충족해야 하는 지급 조건을 확인합니다."],"faq":[],"path":"articles/diag/06/"},{"id":"disab-0","cat":"hospital","cat_name":"병원비보험","doc":"disab","doc_name":"후유장해","index":0,"title":"질병후유장해","definition":"질병후유장해는 질병으로 남은 장해가 계약의 장해분류표와 지급 기준에 해당할 때 보장하는 담보입니다.","explanation":["질병을 진단받거나 치료를 오래 받았다는 사실만으로 후유장해가 인정되는 것은 아닙니다. 치료 후 남은 기능의 손상 정도와 증상의 고정 여부를 장해분류표의 기준에 맞추어 판단합니다.","장해는 원칙적으로 회복할 가망이 없는 정신적·육체적 훼손 상태를 뜻합니다. 치료 과정에서 일시적으로 나타난 증상과 구분하며, 한시적으로 남는 장해는 별도 인정 요건이 있는지 확인합니다.","장해지급률에 가입금액을 곱하는 구조에서는 장해율과 보장하는 지급률 범위가 중요합니다. 동일 질병으로 여러 장해가 남았을 때도 무조건 더하는 것이 아니라 부위별 판정 기준과 합산 규정을 살핍니다.","장해의 판정 시점과 악화된 상태의 재평가 조건은 가입시기·상품에 따라 다릅니다. 국가의 장애 인정과 보험계약의 장해 판정은 기준이 다르므로 어느 한쪽 결과만으로 보험금 여부를 단정하지 않습니다."],"practical":["질병 진단 시점, 치료 경과, 남은 기능 손상을 구분해 정리하고 해당 계약의 장해분류표를 의료기록과 대조합니다.","후유장해 보장과 납입면제 요건을 각각 확인합니다. 같은 장해라도 적용되는 지급률과 계약상 효과가 다를 수 있습니다."],"faq":[],"path":"articles/disab/01/"},{"id":"disab-1","cat":"hospital","cat_name":"병원비보험","doc":"disab","doc_name":"후유장해","index":1,"title":"상해후유장해","definition":"상해후유장해는 사고로 인한 상해의 직접적인 결과로 장해가 남았을 때 계약의 기준에 따라 보장합니다.","explanation":["상해후유장해를 검토할 때는 사고의 발생과 이후 남은 장해를 연결해 살펴야 합니다. 현재 기능이 불편하다는 사실 외에 그 상태가 보장하는 상해의 결과인지가 중요합니다.","장해는 치료가 끝난 뒤에도 남는 기능 손상을 중심으로 판단합니다. 치료 중의 통증이나 일시적인 움직임 제한을 곧바로 영구장해로 보지 않으며, 증상이 고정되는 시점과 부위별 평가 기준을 확인합니다.","장해분류표에는 장해의 정도에 따른 지급 기준이 정해져 있습니다. 같은 사고로 여러 부위에 장해가 생겨도 적용 가능한 합산 규정과 부위별 예외를 함께 읽어야 합니다.","판정 시점에 지급률이 확정되지 않은 경우나 이후 상태가 악화된 경우를 다루는 조항도 있습니다. 보장하는 장해 범위와 판정기간은 가입시기·상품에 따라 다르므로 현재 기준을 과거 계약에 그대로 적용하지 않습니다."],"practical":["사고 기록, 초기 진료기록, 치료 경과와 현재 상태를 시간순으로 정리해 사고와 장해의 관련성을 확인합니다.","고객이 다른 제도의 장해 판정을 받았더라도 해당 보험의 장해분류표와 인정 요건을 별도로 검토합니다."],"faq":[],"path":"articles/disab/02/"},{"id":"disab-2","cat":"hospital","cat_name":"병원비보험","doc":"disab","doc_name":"후유장해","index":2,"title":"장해분류표 읽는 법","definition":"장해분류표는 신체의 기능 손상을 보험계약의 장해 정도와 지급 기준으로 연결하는 판단표입니다.","explanation":["먼저 총칙에서 장해와 영구적인 상태, 치유된 후의 의미를 읽습니다. 표에 적힌 신체부위와 지급률만 찾으면 치료 과정의 일시적 증상과 장해를 구분하는 기준을 놓칠 수 있습니다.","다음으로 해당 신체부위의 판정 기준을 확인합니다. 장해분류표에 직접 기재되지 않은 상태를 유사한 기준으로 판단하는 조항이 있더라도, 최저 지급 수준에 미치지 못한 손상까지 모두 인정된다는 의미는 아닙니다.","여러 장해가 함께 남은 경우에는 동일 질병·동일 상해인지, 다른 원인으로 발생했는지 구분합니다. 합산 원칙이 있어도 신체부위별로 별도 기준을 정할 수 있으므로 지급률을 임의로 더하지 않습니다.","장해판정 시기를 별도로 정한 항목과 이후 악화된 상태를 다루는 규정도 함께 확인합니다. 적용 분류표와 지급 방식은 가입시기·상품에 따라 다르며 다른 제도의 장애등급과 그대로 대응하지 않습니다."],"practical":["총칙, 해당 부위의 정의, 판정 방법, 합산 예외, 담보의 지급사유 순서로 확인한 내용을 기록합니다.","의학적 기능 평가와 보험금 계산을 구분하고, 장해율에 관한 이견은 계약이 정한 판정 절차에 따라 확인하도록 안내합니다."],"faq":[],"path":"articles/disab/03/"},{"id":"liab-0","cat":"hospital","cat_name":"병원비보험","doc":"liab","doc_name":"배상책임","index":0,"title":"자녀 · 일상 · 가족 일상생활배상책임","definition":"일상생활배상책임은 일상생활의 우연한 사고로 타인에게 손해를 주어 법률상 배상책임을 부담할 때 보장합니다.","explanation":["이 담보는 피보험자 자신의 재산 손해를 보장하는 보험과 다릅니다. 타인의 신체나 재물에 손해가 발생하고 피보험자에게 법률상 책임이 있는지를 먼저 살핍니다.","자녀배상책임과 가족일상생활배상책임은 피보험자 범위가 다를 수 있습니다. 가족형도 배우자, 동거 친족, 별거하는 자녀 등에 관한 생계·거주 조건이 정해질 수 있으므로 가족이라는 이유만으로 모두 포함한다고 설명하지 않습니다.","주택 사고에서는 증권에 기재된 주택과 실제 소유·거주 관계를 확인합니다. 누수 원인이 누구의 책임인지와 보장 대상 주택인지에 따라 판단이 달라지며, 해당 조건은 가입시기·상품에 따라 다릅니다.","실제 손해를 보상하는 구조이므로 여러 계약이 있다고 손해액을 넘겨 받을 수 있는 것으로 안내하지 않습니다. 자기부담금과 다수계약의 분담 방식도 가입 담보별로 확인합니다."],"practical":["기존 계약에서 피보험자와 대상 주택을 확인하고 이사나 가족의 거주 형태 변화가 있으면 변경 필요 여부를 점검합니다.","사고가 생기면 피해 상황과 책임 관계부터 확인하고, 선의로 대신 지급한 돈이 모두 보장되는 것은 아니라는 점을 설명합니다."],"faq":[],"path":"articles/liab/01/"},{"id":"liab-1","cat":"hospital","cat_name":"병원비보험","doc":"liab","doc_name":"배상책임","index":1,"title":"배상책임 보상 사례","definition":"배상책임 사례는 사고의 원인, 법률상 책임을 지는 사람, 가입 담보의 범위를 순서대로 확인해 판단합니다.","explanation":["주택 누수로 아랫집에 손해가 생긴 경우, 거주자가 누구인지와 별개로 누수 원인에 대한 책임이 누구에게 있는지 확인해야 합니다. 임차인이 비용을 먼저 냈다는 이유만으로 임차인의 배상책임보험에서 반드시 지급되는 것은 아닙니다.","자녀배상책임에 가입했어도 부모 소유 주택의 관리 책임으로 생긴 누수를 자녀 사고로 볼 수는 없습니다. 책임을 부담하는 사람과 계약의 피보험자가 일치하는지 확인하는 것이 핵심입니다.","누수 탐지나 직접 관련 수리가 추가 손해를 막기 위한 비용으로 인정될 수 있지만, 모든 보수비가 동일하게 취급되지는 않습니다. 비용을 쓴 목적과 누수 방지와의 관련성을 구분해 검토합니다.","운동 중 상대방이 다친 경우에도 다쳤다는 결과만으로 배상책임이 확정되지는 않습니다. 사고 경위와 규칙 위반 등을 살펴 책임 유무를 판단하며, 실제 보장 여부는 가입시기·상품에 따라 다릅니다."],"practical":["누수 위치와 손상 부위를 촬영하고 원인 조사 내역, 공사 항목, 비용 증빙을 나누어 보관하도록 안내합니다.","유사 사례의 지급 결과를 그대로 약속하지 말고 해당 사고의 책임자, 피해자, 대상 주택 및 비용 성격을 정리해 확인합니다."],"faq":[],"path":"articles/liab/02/"},{"id":"driver-0","cat":"hospital","cat_name":"병원비보험","doc":"driver","doc_name":"운전자보험","index":0,"title":"교통사고처리지원금(형사합의금)","definition":"교통사고처리지원금은 계약에서 정한 교통사고로 부담하는 형사합의 관련 비용을 보장하는 담보입니다.","explanation":["이 담보를 확인할 때는 사고 내용과 피해자의 상태, 실제 합의 내용을 나누어 살핍니다. 담보에 가입했다는 사실만으로 모든 교통사고의 합의금이 지급되는 것은 아니며 약관의 사고 요건에 해당해야 합니다.","청구에는 피해자의 진단 내용, 합의금액이 적힌 합의서와 실제 지급 내역 등이 필요할 수 있습니다. 공탁을 한 경우에는 공탁과 출금에 관련된 자료를 추가로 확인하므로 합의서만으로 모든 지급 절차가 끝난다고 보지 않습니다.","다수계약의 보상은 약관에 따라 비례하여 나누는 구조가 있습니다. 가입금액을 모두 합한 금액이 실제 수령액이 되는 것으로 설명하지 않으며, 보장 범위·한도·지급 절차는 가입시기·상품에 따라 다릅니다."],"practical":["사고와 합의 경과, 실제 송금 내역을 정리하고 청구에 필요한 자료를 계약별로 확인합니다.","합의 전에 보장 가능한 사고인지와 지급 요건을 확인하도록 안내하고, 가입금액만 보고 지급을 약속하지 않습니다."],"faq":[],"path":"articles/driver/01/"},{"id":"driver-1","cat":"hospital","cat_name":"병원비보험","doc":"driver","doc_name":"운전자보험","index":1,"title":"벌금","definition":"운전자 벌금 담보는 계약에서 정한 사고로 부담하는 벌금에 대해 보장하는 비용 담보입니다.","explanation":["청구를 검토할 때는 법원의 판단 내용과 벌금 납부 사실을 확인합니다. 벌금영수증과 판결 또는 약식명령 관련 자료가 필요한 이유는 어떤 사고로 어느 비용을 부담했는지 구분하기 위해서입니다.","대인 사고의 벌금과 대물 사고의 벌금을 별도 담보로 구성하는 경우가 있습니다. 운전자보험에 가입했다는 이유만으로 사고 종류와 관계없이 모든 벌금이 포함되는 것으로 안내하지 않습니다.","실제 비용을 보상하는 담보에는 다수계약의 비례보상 규정이 적용될 수 있습니다. 지급 한도와 보장 대상, 제외 사유는 가입시기·상품에 따라 다르므로 현재 유효한 계약의 조건을 기준으로 검토합니다."],"practical":["고객이 받은 납부 안내만 보고 판단하지 말고 사고 관련 자료와 벌금의 근거를 확인합니다.","기존 계약의 대인·대물 벌금 담보 가입 여부와 중복 계약을 점검한 뒤 실제 부담액에 대한 보상 구조를 설명합니다."],"faq":[],"path":"articles/driver/02/"},{"id":"driver-2","cat":"hospital","cat_name":"병원비보험","doc":"driver","doc_name":"운전자보험","index":2,"title":"변호사선임비용","definition":"변호사선임비용 담보는 계약에서 정한 자동차사고의 법적 절차에서 실제 부담한 선임비용을 보장합니다.","explanation":["변호사를 선임했다는 사실만으로 지급이 결정되는 것은 아닙니다. 구속이나 공소제기 등 어떤 절차를 지급 요건으로 정했는지, 경찰 조사 단계까지 포함하는 담보인지 구분해 확인합니다.","실제로 부담한 선임비용 중 보장 대상이 되는 금액을 기준으로 공제와 한도를 적용하는 구조가 있습니다. 따라서 담보의 가입금액은 사고마다 반드시 전액 지급되는 금액과 같지 않습니다.","다른 계약에서도 같은 선임비용을 보장한다면 약관의 분담 규정에 따라 나누어 지급할 수 있습니다. 한 계약의 청구를 포기해도 다른 계약에서 전액을 받는 것으로 바뀌지 않는 조항이 있을 수 있습니다.","보장하는 법적 절차와 사고 범위, 자기부담금과 한도는 가입시기·상품에 따라 다릅니다. 형사 절차 관련 담보를 민사소송 비용 전체의 보장으로 확대하여 안내하지 않습니다."],"practical":["사고 조사와 재판의 진행 단계, 선임계약 및 비용 지출을 구분해 확인하고 필요한 증빙을 준비하도록 안내합니다.","청구 전 해당 사고의 지급사유와 면책 조항을 확인하고, 보장 여부를 추정해 변호사 비용을 확약하지 않습니다."],"faq":[],"path":"articles/driver/03/"},{"id":"driver-3","cat":"hospital","cat_name":"병원비보험","doc":"driver","doc_name":"운전자보험","index":3,"title":"교통사고 부상치료비","definition":"교통사고 부상치료비는 교통사고로 입은 부상에 대해 가입한 담보의 조건에 따라 보장하는 항목입니다.","explanation":["교통사고의 범위와 부상 인정 기준을 해당 계약에서 먼저 확인합니다.","지급금액을 판단할 때는 실제 치료 내용과 담보의 지급 기준을 구분해 살펴봅니다.","구체적인 지급기준과 제외사항은 가입시기·상품에 따라 다르므로 담보명만으로 지급을 확약하지 않습니다."],"practical":["사고 경위와 부상에 관한 진료 자료를 확인한 뒤 가입 담보와 대조합니다.","치료비 보장과 다른 교통사고 비용 담보를 구분해 안내합니다."],"faq":[],"path":"articles/driver/04/"},{"id":"surg-0","cat":"hospital","cat_name":"병원비보험","doc":"surg","doc_name":"수술비","index":0,"title":"수술의 정의와 사례","definition":"보험에서의 수술은 치료 목적과 시행 방법이 해당 담보의 정의에 맞는지를 확인해 판단합니다.","explanation":["약관에는 의사가 직접 치료를 위해 필요하다고 인정하고 정해진 의료기관에서 관리 아래 시행하는 처치를 수술로 정의하는 구조가 있습니다. 병원에서 수술이라고 안내받았다는 사실과 계약상 수술에 해당하는지는 구분해 확인합니다.","기구를 이용해 신체를 절단하거나 절제하는 조작을 수술 정의에 포함하는 경우가 있습니다. 다만 이것만으로 모든 처치의 보장 여부를 결정할 수 없으며, 포함·제외하는 방법과 추가 인정 기준을 함께 읽어야 합니다.","암수술 담보라면 해당 암을 직접 치료하기 위한 수술인지가 중요합니다. 특정 질병의 수술비도 병명과 시행한 처치를 연결해 검토해야 하므로 수술명만 같다고 같은 결과가 나오는 것은 아닙니다.","수술의 정의와 대상 질병, 지급 방식은 가입시기·상품에 따라 다릅니다. 과거 다른 계약에서 받은 보험금 사례를 현재 계약의 지급 기준으로 대신하지 않습니다."],"practical":["수술명, 시행 방법, 치료 대상 질병과 치료 목적을 확인할 수 있는 기록을 정리합니다.","가입 담보의 수술 정의와 지급사유를 각각 읽고, 새로운 치료법은 포함 여부를 확인한 뒤 안내합니다."],"faq":[],"path":"articles/surg/01/"},{"id":"surg-1","cat":"hospital","cat_name":"병원비보험","doc":"surg","doc_name":"수술비","index":1,"title":"생명보험 종수술비와 손해보험 특정수술비","definition":"종수술비와 특정수술비는 수술을 분류하는 방식과 보장 대상이 달라 해당 담보의 기준을 따로 읽어야 합니다.","explanation":["종수술비는 계약의 수술분류표에서 해당 수술이 어디에 들어가는지를 먼저 확인하는 방식으로 이해합니다. 담보명에 적힌 종의 구분만 보고 수술 규모나 실제 병원비와 동일하게 연결해서는 안 됩니다.","특정수술비는 지정된 질병이나 수술을 대상으로 구성됩니다. 예를 들어 특정 종양을 직접 치료하는 수술을 정한 경우에는 실제 질병과 수술 목적이 그 범위에 해당하는지를 함께 확인합니다.","같은 수술이라도 가입한 담보에 따라 확인해야 하는 분류와 지급사유가 다릅니다. 보험 종류의 큰 이름만으로 판단하지 않고, 현재 계약에 포함된 수술분류표와 특약을 기준으로 검토합니다.","수술의 분류, 지급금액과 횟수 제한은 가입시기·상품에 따라 다릅니다. 여러 수술을 함께 받았거나 같은 질병으로 다시 수술한 경우에는 각 담보의 별도 지급 규정을 확인해야 합니다."],"practical":["기존 증권에서 수술 담보를 구분하고 수술명과 질병명에 각각 대응하는 조건을 표시합니다.","청구 가능한 담보를 검토할 때 한 담보의 지급 결과를 다른 수술비 담보에 그대로 적용하지 않습니다."],"faq":[],"path":"articles/surg/02/"},{"id":"hosp-etc-0","cat":"hospital","cat_name":"병원비보험","doc":"hosp-etc","doc_name":"입원일당 · 기타","index":0,"title":"입원일당","definition":"입원일당은 계약이 정한 입원 요건을 충족한 기간에 대해 약정된 일당을 지급하는 보장입니다.","explanation":["입원 여부를 볼 때는 병실에 머물렀다는 사실뿐 아니라 치료 필요성과 입원의 목적을 확인합니다. 의사의 관리 아래 치료에 전념하는 상태 등 약관이 정한 입원의 의미를 먼저 살펴야 합니다.","질병입원일당, 수술입원일당, 중환자실 입원일당은 지급 조건이 서로 다릅니다. 입원 원인이 무엇인지와 수술 여부, 치료한 병실 및 의료기관의 종류를 나누어 확인합니다.","지급하는 입원일수에는 한도가 있을 수 있으며 반복 입원을 같은 입원으로 계산하는 규정도 있습니다. 병원을 옮기거나 퇴원 후 다시 입원했다고 언제나 한도가 새로 시작되는 것으로 설명하지 않습니다.","요양병원을 제외하거나 별도 보장하는 계약도 있습니다. 입원 인정 기준, 보장 시작 시점, 지급일수와 한도는 가입시기·상품에 따라 다르므로 특정 계약의 조건을 공통 기준처럼 사용하지 않습니다."],"practical":["입퇴원일, 입원 원인, 의료기관 및 병실 종류를 확인한 뒤 가입 담보와 하나씩 연결합니다.","반복 입원은 이전 입원과의 관계를 정리하고, 같은 질병으로 합산하는 기준과 보장이 다시 시작되는 조건을 확인합니다."],"faq":[],"path":"articles/hosp-etc/01/"},{"id":"hosp-etc-1","cat":"hospital","cat_name":"병원비보험","doc":"hosp-etc","doc_name":"입원일당 · 기타","index":1,"title":"기타 병원비 담보","definition":"기타 병원비 담보는 특정 치료·검사·병실·의료서비스의 이용을 조건으로 추가 보장을 제공하는 담보입니다.","explanation":["병원비 보장은 실손이나 진단비 외에도 중환자실 입원, 특정 항암치료, 간호·간병통합서비스 이용 등으로 나뉩니다. 고객이 병원에서 어떤 치료와 서비스를 받았는지에 따라 적용할 담보가 달라집니다.","간호·간병통합서비스 입원일당은 일반 입원과 별도로 해당 서비스를 이용했는지가 중요합니다. 특정 의료기관이나 병동 요건, 요양병원 제외 여부를 정한 계약이라면 그 조건도 충족해야 합니다.","특정 치료비나 검사비는 진단명만으로 지급하지 않을 수 있습니다. 해당 치료의 시행, 급여 여부, 정해진 진료행위 또는 시행기관 등 담보별 요건을 확인해야 합니다.","입원일당과 통원일당, 치료비의 지급 단위 및 한도는 서로 다릅니다. 반복 이용이 가능한 담보도 횟수나 기간 제한이 있을 수 있으며 구체적 조건은 가입시기·상품에 따라 다릅니다."],"practical":["담보를 많이 나열하기보다 고객이 실제 이용할 수 있는 진료 상황과 연결해 보장 조건을 설명합니다.","청구 안내 시 진단서에 더해 치료명, 서비스 이용 여부, 의료기관 구분을 입증할 자료가 필요한지 확인합니다."],"faq":[],"path":"articles/hosp-etc/02/"},{"id":"whole-0","cat":"death","cat_name":"사망보험","doc":"whole","doc_name":"종신보험","index":0,"title":"종신보험의 구조","definition":"종신보험은 피보험자가 사망할 때 약정한 보험금을 지급하도록 평생의 사망 위험을 보장하는 보험입니다.","explanation":["보험기간이 종신이라는 말은 사망보장의 종료 시점을 특정 나이로 정하지 않는다는 뜻입니다. 보험료를 내는 기간과 보장받는 기간은 서로 다르므로, 납입을 마쳤다는 이유로 계약이 끝난다고 설명하면 안 됩니다.","사망보험금은 가입금액만으로 결정되지 않을 수 있습니다. 계약 경과에 따라 금액이 늘어나는 구조나 일정 조건에서 감액하는 구조가 있으므로 지급기준을 확인해야 합니다.","사망 시 받는 보험금과 살아 있을 때 해지하여 받는 돈은 계산 목적이 다릅니다. 해약환급금이 적거나 없는 유형도 있어, 사망보장 금액을 중도에 찾을 수 있는 돈으로 이해하면 곤란합니다."],"practical":["설명할 때는 보험기간, 납입기간, 사망보험금, 해약환급금을 구분하여 고객이 각각의 의미를 확인하도록 합니다.","같은 종신보험이라도 지급금액의 변화와 감액 조건은 가입시기·상품에 따라 다릅니다. 현재 계약의 지급기준부터 확인합니다."],"faq":[],"path":"articles/whole/01/"},{"id":"whole-1","cat":"death","cat_name":"사망보험","doc":"whole","doc_name":"종신보험","index":1,"title":"CI보험과 GI보험","definition":"CI와 GI는 질병 보장의 명칭이며, 실제 지급 여부는 약관에 정한 질병의 정의와 선지급 구조로 판단합니다.","explanation":["CI는 중대한 질병이나 수술 등 약정한 상태가 발생하면 사망보험금의 일부를 먼저 지급하는 구조가 대표적입니다. 이때 먼저 받은 금액만큼 나중의 사망보험금이 줄어드는지 함께 확인해야 합니다.","암이나 뇌졸중이라는 진단을 받았어도 약관이 정한 중대한 상태와 맞지 않으면 CI 보험금이 지급되지 않을 수 있습니다. 병명과 보험금 지급요건을 같은 뜻으로 설명하지 않습니다.","GI라는 이름만으로 모든 질병을 보장하거나 진단만 있으면 지급된다고 단정할 수 없습니다. 비교하려는 계약의 질병 목록, 진단 요건, 제외 조건을 개별적으로 확인해야 합니다."],"practical":["질병이 발생했을 때 받을 돈과 그 뒤 남는 사망보장 금액을 나누어 안내합니다.","기존 계약을 점검할 때는 이름의 인상보다 실제 가입한 주계약과 특약의 조건을 먼저 대조합니다. 세부 범위는 가입시기·상품에 따라 다릅니다."],"faq":[],"path":"articles/whole/02/"},{"id":"whole-2","cat":"death","cat_name":"사망보험","doc":"whole","doc_name":"종신보험","index":2,"title":"\"중대한\"의 의미와 컨셉","definition":"보험에서 중대하다는 표현은 일상적인 병의 심각성이 아니라 약관이 별도로 정한 지급요건을 뜻합니다.","explanation":["중대한 질병 보장은 진단명 외에 질병의 상태나 검사 결과를 함께 요구할 수 있습니다. 따라서 고객이 느끼는 증상의 심각성이나 치료비 규모만으로 해당 여부를 판단하지 않습니다.","예를 들어 중대한 뇌졸중의 정의에 영구적인 신경학적 결손을 요구하는 계약이 있습니다. 이 경우 뇌졸중 진단을 받았다는 사실과 약관에서 정한 후유 상태가 남았다는 사실을 구별하여 확인해야 합니다.","중대한 급성심근경색증에서도 진단에 사용하는 검사와 증상 요건을 별도로 정한 사례가 있습니다. 구체적인 진단 기준과 제외 범위는 가입시기·상품에 따라 다르므로 다른 계약의 기준을 그대로 적용하지 않습니다."],"practical":["상담에서는 보장하는 병명을 읽는 데 그치지 않고 지급요건과 보장에서 제외되는 상태를 함께 설명합니다.","보험금 청구 시에는 진단서 외에 어떤 검사와 진료기록이 해당 요건을 뒷받침하는지 확인합니다. 지급 여부를 설계사가 미리 확정하지 않습니다."],"faq":[],"path":"articles/whole/03/"},{"id":"whole-3","cat":"death","cat_name":"사망보험","doc":"whole","doc_name":"종신보험","index":3,"title":"납입면제 · 추가납입 · 중도인출 · 납입정지 · 연금전환","definition":"납입면제와 납입정지, 추가납입과 중도인출, 연금전환은 각각 목적과 작동 조건이 다른 계약 기능입니다.","explanation":["납입면제는 약정한 질병 등의 사유가 생겼을 때 이후 보험료 납입을 면제하는 기능입니다. 납입정지는 일정 조건에서 납입을 멈추는 기능으로, 적립금에서 비용이 차감될 수 있어 면제와 구분해야 합니다.","추가납입은 정해진 보험료 외의 돈을 더 넣는 것이고, 중도인출은 적립금 일부를 꺼내 쓰는 것입니다. 가능 시점과 한도가 있으므로 추가납입한 돈을 언제나 별도로 해지할 수 있다고 설명하지 않습니다.","연금전환은 계약의 가치를 연금 재원으로 활용하는 기능입니다. 전환 방식에 따라 기존 사망보장이 달라질 수 있으므로 전환 전후에 받을 돈과 유지되는 보장을 확인해야 합니다."],"practical":["사용 가능한 기능인지, 별도 신청이 필요한지, 실행 후 적립금과 보장에 어떤 변화가 생기는지를 순서대로 확인합니다.","기능의 적용 범위는 가입시기·상품에 따라 다릅니다. 설계 화면에 넣은 예시가 실제 신청까지 끝난 상태인지는 별도로 확인합니다."],"faq":[],"path":"articles/whole/04/"},{"id":"termlife-0","cat":"death","cat_name":"사망보험","doc":"termlife","doc_name":"정기보험","index":0,"title":"정기보험의 구조와 활용","definition":"정기보험은 정해진 보험기간 안에 발생하는 사망을 보장하는 보험입니다.","explanation":["종신보험과 구분하는 핵심은 보장기간에 끝이 있다는 점입니다. 만기까지 보험료를 내는 계약인지, 먼저 납입을 끝내고 보장만 계속되는 계약인지도 나누어 확인해야 합니다.","순수보장형과 만기환급형처럼 만기 때 돌려받는 돈의 구조가 다른 유형이 있습니다. 정기보험이라는 이름만으로 만기보험금이 있거나 없다고 판단하면 안 됩니다.","보험기간 중 사망보험금의 변화나 종신 전환, 연금전환 같은 기능은 계약마다 다릅니다. 부가 기능이 있다는 이유로 만기 이후에도 사망보장이 자동으로 이어진다고 설명하지 않습니다."],"practical":["고객이 사망보장을 필요로 하는 기간과 계약의 만기 시점을 함께 살펴보며, 만기 뒤의 보장 공백을 확인합니다.","가입시기·상품에 따라 보장기간과 환급 구조가 다르므로 보험기간, 납입기간, 만기 지급금액을 따로 기록하여 안내합니다."],"faq":[],"path":"articles/termlife/01/"},{"id":"accdeath-0","cat":"death","cat_name":"사망보험","doc":"accdeath","doc_name":"재해사망과 상해사망","index":0,"title":"재해사망과 상해사망의 차이","definition":"재해사망과 상해사망은 우발적인 외부 사고로 인한 사망을 다루지만 약관이 위험을 정하는 방식에 차이가 있습니다.","explanation":["재해는 약관에 붙은 재해분류표 등에서 정한 사고 범위를 확인하는 방식이 사용됩니다. 사고의 이름만 보고 판단하기보다 분류표에 포함되는지와 제외 규정을 함께 살펴야 합니다.","상해는 급격하고도 우연한 외래의 사고로 신체에 손상을 입었다는 요건을 중심으로 판단합니다. 사고가 있었다는 사실과 그 사고 때문에 사망했다는 인과관계가 모두 검토 대상입니다.","두 담보가 비슷해 보여도 감염병 등 개별 위험의 포함 여부가 같다고 단정할 수 없습니다. 적용되는 분류와 예외는 가입시기·상품에 따라 다르므로 같은 사고에 대한 결론도 달라질 수 있습니다."],"practical":["보험증권에 재해사망인지 상해사망인지 정확히 표시하고, 해당 정의와 분류표를 맞춰 확인합니다.","사고 경위와 치료 과정, 사망 원인을 구분해 정리합니다. 담보 명칭이 비슷하다는 이유로 한 계약의 지급 결과를 다른 계약에 그대로 적용하지 않습니다."],"faq":[],"path":"articles/accdeath/01/"},{"id":"accdeath-1","cat":"death","cat_name":"사망보험","doc":"accdeath","doc_name":"재해사망과 상해사망","index":1,"title":"상해의 입증요소: 외래성 · 우연성 · 급격성","definition":"상해를 판단할 때는 외부 원인, 뜻하지 않은 발생, 돌발적인 사고라는 요소와 손상 결과를 함께 확인합니다.","explanation":["외래성은 신체 내부의 질병이나 체질적 요인만으로 생긴 결과인지, 외부 요인이 작용한 결과인지를 구분하는 기준입니다. 몸 밖에서 어떤 사건이 있었는지 구체적으로 확인해야 합니다.","우연성은 피보험자가 의도하거나 통상 예상한 결과인지와 관련됩니다. 급격성은 원인에서 상해 결과에 이르는 과정이 갑작스럽고 돌발적이었는지를 살피는 요소입니다.","각 요소가 인정되어도 그 사고와 신체 손상 또는 사망 사이의 관계를 따져야 합니다. 질병과 사고가 함께 작용한 사례에서는 진료기록과 의학적 판단 등 여러 자료를 종합하게 됩니다."],"practical":["사고 전 상태, 발생 과정, 사고 후 증상과 치료 경과를 시간 순으로 정리하여 원인과 결과가 섞이지 않게 합니다.","진단명 하나만으로 상해를 확정하지 않습니다. 사고 기록과 진료기록에서 확인되는 사실을 바탕으로 보험금 심사에 필요한 자료를 준비합니다."],"faq":[],"path":"articles/accdeath/02/"},{"id":"disdeath-0","cat":"death","cat_name":"사망보험","doc":"disdeath","doc_name":"질병사망과 일반사망","index":0,"title":"질병사망과 일반사망의 차이","definition":"질병사망은 질병을 원인으로 한 사망을 대상으로 하고, 일반사망 담보는 더 넓은 사망 위험을 약정한 범위에서 다룹니다.","explanation":["상해사망 담보는 상해의 직접 결과로 사망한 경우를 다루며 질병으로 인한 사망을 제외하는 구조가 있습니다. 따라서 사망 담보를 비교할 때는 보험금액만이 아니라 원인에 관한 제한을 먼저 확인해야 합니다.","일반사망이라고 불리는 보장도 모든 상황을 아무 조건 없이 지급한다는 뜻은 아닙니다. 계약의 지급사유와 보험금을 지급하지 않는 사유를 함께 읽어야 실제 범위가 드러납니다.","질병과 외부 사고가 함께 작용한 경우에는 원인을 단순히 나누기 어려울 수 있습니다. 사망에 이른 경과와 의학적 자료를 살펴 해당 담보의 지급요건에 맞는지를 판단합니다."],"practical":["가입한 사망담보를 일반사망, 질병사망, 상해·재해사망으로 구분하고 각각의 보장기간을 확인합니다.","사망진단서의 표현만으로 지급 여부를 확정하지 말고 사고 경위와 치료기록을 함께 검토합니다. 세부 조건은 가입시기·상품에 따라 다릅니다."],"faq":[],"path":"articles/disdeath/01/"},{"id":"disdeath-1","cat":"death","cat_name":"사망보험","doc":"disdeath","doc_name":"질병사망과 일반사망","index":1,"title":"사망의 원인과 확률, 보장범위","definition":"사망보장을 설계할 때는 사망 원인의 빈도와 계약이 실제로 보장하는 원인을 구분해야 합니다.","explanation":["전체 사망을 다루는 보장과 특정 사고에 한정한 보장은 범위가 다릅니다. 사고사망 보험금이 크더라도 질병으로 인한 사망을 같은 금액으로 보장한다고 볼 수 없습니다.","개별 사고의 보상 판단에서는 그 원인이 무엇인지, 사고와 사망 사이에 관계가 있는지가 핵심입니다. 질병을 앓고 있었다는 사실만으로 외부 사고의 영향을 배제할 수는 없으며 구체적인 기록을 확인해야 합니다.","사망 원인 통계는 집단의 현황을 보여 주는 자료입니다. 이 항목에서는 확인되지 않은 비율로 특정 고객의 사망 가능성이나 보험금 지급 가능성을 추정하지 않고 보장 범위를 점검하는 데 집중합니다."],"practical":["원인별 보장금액을 설명할 때는 일반사망과 사고에 한정한 추가 보장을 나누어 표시합니다.","원인 불명이나 복합 원인의 사망은 자료에 따라 판단이 달라질 수 있습니다. 확인된 사실과 아직 확인이 필요한 부분을 구분하여 청구를 안내합니다."],"faq":[],"path":"articles/disdeath/02/"},{"id":"fixed-0","cat":"annuity","cat_name":"저축·연금보험","doc":"fixed","doc_name":"공시이율형 상품","index":0,"title":"연금저축: 세액공제의 개념과 장단점","definition":"연금저축은 노후자금 마련을 위해 납입하며 세법 요건에 따라 납입액의 세액공제를 받을 수 있는 제도입니다.","explanation":["세액공제는 납부할 세금을 줄이는 제도이며 보험의 운용 수익과는 구분됩니다. 세액공제를 받을 수 있다는 사실을 납입액 전체에 확정 수익이 붙는 것처럼 설명하면 안 됩니다.","연금을 받을 때와 연금 외의 방식으로 인출할 때는 과세 방식이 달라질 수 있습니다. 납입 단계의 혜택만 보지 말고 수령 계획과 중도해지 가능성을 함께 검토해야 합니다.","연금저축보험은 계약 체결·관리 비용 등을 차감하여 적립하는 보험입니다. 중도해지 시 환급금이 납입보험료보다 적을 수 있으므로 세금과 해지 손실을 별개의 항목으로 확인합니다."],"practical":["고객의 납입 여력과 연금으로 사용할 시점을 확인한 후 장기간 유지할 수 있는 계획인지 살펴봅니다.","공제 가능 여부와 수령 단계의 세금은 관련 법령과 개인의 조건을 확인합니다. 가입시기·상품에 따른 차이가 있으므로 세율이나 환급액을 일률적으로 약속하지 않습니다."],"faq":[],"path":"articles/fixed/01/"},{"id":"fixed-1","cat":"annuity","cat_name":"저축·연금보험","doc":"fixed","doc_name":"공시이율형 상품","index":1,"title":"연금펀드","definition":"연금펀드는 연금 목적의 자금을 펀드로 운용하는 방식으로, 연금저축보험과 운용 구조를 구분해 살펴야 합니다.","explanation":["연금저축이라는 제도와 그 안에서 선택하는 운용 방식을 나누어 이해해야 합니다. 펀드로 운용한다는 점을 보험의 공시이율 적립 방식과 혼동하지 않습니다.","확인할 내용은 투자 대상과 위험, 비용, 인출 및 연금 수령 조건입니다. 연금 목적이라는 이유만으로 원금이나 수익이 보장된다고 설명하지 않습니다.","세액공제와 수령 단계의 과세는 운용 성과와 별개의 문제입니다. 가입시기·상품에 따라 적용 내용이 다르므로 납입 때의 혜택과 받을 때의 조건을 함께 확인합니다."],"practical":["고객이 원하는 운용 방식과 연금으로 쓸 시점을 확인하고 해당 펀드의 구체적인 조건을 살펴봅니다.","연금저축보험의 비용·보증 조건을 펀드에 그대로 적용하여 비교하지 않습니다."],"faq":[],"path":"articles/fixed/02/"},{"id":"fixed-2","cat":"annuity","cat_name":"저축·연금보험","doc":"fixed","doc_name":"공시이율형 상품","index":2,"title":"연금보험","definition":"연금보험은 정해진 조건에 따라 적립한 재원을 연금으로 받도록 설계한 보험입니다.","explanation":["공시이율형에서는 적립에 적용하는 이율이 달라질 수 있습니다. 가입 당시 제시한 예시와 실제 연금액이 같은 조건으로 계산되는지를 확인해야 합니다.","납입보험료 전액에 이율을 적용하는 것으로 이해하면 안 됩니다. 계약 체결·유지와 보장에 필요한 비용을 차감하는 구조를 함께 살펴야 합니다.","연금저축과 연금보험의 세금 혜택은 구분해야 합니다. 세액공제 여부와 보험차익의 비과세 요건을 각각 확인하며, 가입시기·상품에 따라 수령 방식과 조건이 달라질 수 있습니다."],"practical":["연금을 언제부터 어떤 방식으로 받는지, 예시 금액이 어떤 이율을 가정했는지 확인합니다.","중도에 해지할 때 받을 돈과 연금으로 수령할 돈을 별도로 설명하고, 이율이 낮아지는 경우의 예상 금액도 함께 확인합니다."],"faq":[],"path":"articles/fixed/03/"},{"id":"fixed-3","cat":"annuity","cat_name":"저축·연금보험","doc":"fixed","doc_name":"공시이율형 상품","index":3,"title":"저축보험","definition":"저축보험은 보험계약의 비용과 적립 구조를 통해 자금을 마련하는 저축성보험으로, 은행 예·적금과 구분해야 합니다.","explanation":["보험료에는 적립되는 부분 외에 계약 체결·유지 비용과 위험보장을 위한 비용이 포함될 수 있습니다. 표시된 이율을 납입한 보험료 전체에 그대로 곱하여 예상 금액을 계산하면 실제와 달라질 수 있습니다.","금리연동형에서는 계약자적립액을 계산하는 이율이 변동할 수 있습니다. 최저보증이율이 있더라도 어느 기간과 어떤 금액에 적용되는지 확인해야 하며, 납입원금 전체의 수익률을 뜻한다고 설명하지 않습니다.","중도해지 때 받는 환급금은 납입보험료보다 적거나 없을 수 있습니다. 저축이라는 명칭만으로 원하는 시점에 납입액을 전부 찾을 수 있다고 생각하지 않도록 안내해야 합니다."],"practical":["고객이 자금을 사용할 시점과 계약 유지 가능 기간을 확인하고, 경과기간별 환급금을 함께 살펴봅니다.","가입시기·상품에 따라 적용이율과 비용, 환급 구조가 다릅니다. 보증되는 조건과 단순한 예상 금액을 구분해 설명합니다."],"faq":[],"path":"articles/fixed/04/"},{"id":"fixed-4","cat":"annuity","cat_name":"저축·연금보험","doc":"fixed","doc_name":"공시이율형 상품","index":4,"title":"종신보험을 이용한 저축플랜","definition":"종신보험의 환급금을 활용하는 계획은 사망보장 목적과 중도해지 손실을 먼저 확인한 뒤 검토해야 합니다.","explanation":["종신보험은 피보험자의 사망에 대비하는 보장성보험입니다. 환급률이 제시되거나 납입기간이 짧다고 해서 목돈 마련용 저축성보험으로 바뀌는 것은 아닙니다.","보험료에는 사망보장을 위한 비용과 계약 체결·유지 비용이 포함됩니다. 중도에 해지하면 납입한 보험료보다 적게 받거나 환급금이 없을 수 있으므로 미래에 받을 금액만 강조해서는 안 됩니다.","입출금 기능이나 납입정지 기능이 있더라도 통장처럼 제한 없이 사용하는 구조로 설명하면 오해가 생깁니다. 적립금이 계약 유지에 필요한 비용을 충당하지 못하면 계약이 해지될 수 있는지도 확인해야 합니다."],"practical":["고객의 목적이 유족의 생활보장인지, 정해진 시점에 쓸 자금 마련인지 먼저 구분합니다. 목적과 상품 성격이 맞는지를 설명한 뒤 선택하도록 합니다.","설명할 때는 중도해지 손실과 환급금이 없는 기간을 함께 보여 줍니다. 구체적인 환급 구조와 기능은 가입시기·상품에 따라 다릅니다."],"faq":[],"path":"articles/fixed/05/"},{"id":"variable-0","cat":"annuity","cat_name":"저축·연금보험","doc":"variable","doc_name":"변액투자형 상품","index":0,"title":"변액유니버셜 저축보험(VUL)","definition":"변액유니버셜보험은 펀드 운용실적이 계약 가치에 반영되고 정해진 조건 아래 납입이나 인출 기능을 이용하는 보험입니다.","explanation":["납입한 보험료 전액이 투자되는 것은 아닙니다. 계약 체결·관리 비용과 보장 관련 비용 등을 제외한 금액이 특별계정에 투입되므로 납입액과 투자 원금을 구분해야 합니다.","특별계정의 운용실적에 따라 적립금과 해약환급금 등이 달라집니다. 운용 결과는 계약에 귀속되며 펀드 수익률을 납입보험료 전체에 대한 수익률로 설명해서는 안 됩니다.","유니버셜 기능은 입출금을 허용하는 조건이 있다는 뜻입니다. 납입을 쉬는 동안에도 계약 유지 비용이 발생할 수 있고, 적립금이 부족하면 보장이 이어지지 않을 수 있습니다."],"practical":["저축 목적의 상품인지 사망보장 중심의 상품인지부터 확인합니다. 같은 변액유니버셜이라는 말이 붙어도 계약 목적과 비용 구조가 다를 수 있습니다.","추가납입·중도인출·납입중지의 가능 시점과 제한을 따로 안내합니다. 최저보증 여부와 범위도 가입시기·상품에 따라 다르므로 개별 확인합니다."],"faq":[],"path":"articles/variable/01/"},{"id":"variable-1","cat":"annuity","cat_name":"저축·연금보험","doc":"variable","doc_name":"변액투자형 상품","index":1,"title":"변액연금보험(VA)","definition":"변액연금보험은 펀드 운용을 통해 연금 재원을 마련하며 운용실적과 계약 조건에 따라 수령액이 달라지는 보험입니다.","explanation":["연금을 받기 전에는 보험료에서 비용을 뺀 금액을 특별계정에서 운용합니다. 적립금에는 투자 성과와 각종 비용이 함께 반영되므로 수익률만으로 실제 받을 돈을 계산하면 안 됩니다.","연금을 받기 시작한 뒤의 운용 방식도 확인해야 합니다. 투자실적이 계속 반영되는 방식과 공시이율을 적용하는 방식 등 계약에서 정한 선택에 따라 계산 구조가 달라질 수 있습니다.","최저보증 기능이 있다면 무엇을 언제 보증하는지를 읽어야 합니다. 연금 재원이나 특정 보험금에 대한 보증을 중도해지 환급금까지 항상 보장한다는 뜻으로 넓혀 설명하지 않습니다."],"practical":["가입시기·상품에 따라 연금개시 조건, 운용 방식, 보증 범위가 다릅니다. 고객이 확인한 예시가 어떤 조건을 전제로 하는지 함께 기록합니다.","적립금과 해약환급금, 예상 연금액을 구분하여 설명하고, 연금개시 전후에 비용과 운용 위험이 어떻게 달라지는지 확인합니다."],"faq":[],"path":"articles/variable/02/"},{"id":"variable-2","cat":"annuity","cat_name":"저축·연금보험","doc":"variable","doc_name":"변액투자형 상품","index":2,"title":"변액상품의 펀드 개념과 관리 방법","definition":"변액보험의 펀드는 투자 목적과 대상에 따라 나뉜 특별계정 자산으로, 선택한 운용 방식이 계약 가치에 영향을 줍니다.","explanation":["특별계정은 일반 보험자산과 구분하여 관리됩니다. 주식이나 채권 등 어떤 자산을 대상으로 운용하는지를 확인하고 펀드 이름만으로 위험 수준을 판단하지 않습니다.","운용실적에 따른 이익과 손실이 계약자적립액에 반영되며 운용·관리 보수도 차감됩니다. 따라서 펀드의 성과와 실제 계약의 적립금 변화를 함께 살펴야 합니다.","계약자는 정해진 방법으로 펀드 변경을 신청할 수 있습니다. 이는 펀드 안의 개별 종목 거래를 직접 지시한다는 뜻과는 다르며, 변경 절차와 가능한 범위는 가입시기·상품에 따라 다릅니다."],"practical":["정기적으로 운용 대상, 자산 구성, 성과와 비용을 확인하고 현재 선택이 고객의 투자 목적에 맞는지 점검합니다.","변경 전에는 어떤 펀드에서 어느 펀드로 비중을 바꾸는지, 신청 결과가 계약에 반영되었는지를 확인합니다. 과거 성과만을 근거로 향후 수익을 확정하여 안내하지 않습니다."],"faq":[],"path":"articles/variable/03/"},{"id":"taxfree-0","cat":"annuity","cat_name":"저축·연금보험","doc":"taxfree","doc_name":"비과세와 상품 비교","index":0,"title":"비과세 및 비과세 조건","definition":"보험의 비과세는 일정한 세법 요건을 충족한 보험차익 등에 세금을 부과하지 않는 제도로, 가입만으로 자동 확정되지 않습니다.","explanation":["연금저축의 세액공제와 저축성보험의 보험차익 비과세는 서로 다른 제도입니다. 세액공제를 받는다는 사실을 연금 수령액에 세금이 전혀 없다는 뜻으로 안내하면 안 됩니다.","비과세 판단에는 계약 체결 시기, 유지기간, 납입 방식과 금액 등 여러 조건이 사용됩니다. 단순히 오래 유지했다는 사실만으로 다른 요건까지 충족했다고 볼 수 없습니다.","한도를 판단할 때는 해당 계약 하나만 보는지, 같은 계약자의 다른 계약과 합산하는지 확인해야 합니다. 요건을 충족하지 못한 경우 보험차익이 과세 대상이 될 수 있습니다."],"practical":["가입시기·상품에 따라 적용 조건이 다르므로 계약일, 납입 내역, 관련 계약을 확인한 뒤 세무 판단에 필요한 내용을 정리합니다.","이 항목의 일반 설명으로 개별 계약의 비과세를 확약하지 않습니다. 실제 지급·해지 시점에 적용되는 법령과 계약 변경 이력을 함께 확인합니다."],"faq":[],"path":"articles/taxfree/01/"},{"id":"taxfree-1","cat":"annuity","cat_name":"저축·연금보험","doc":"taxfree","doc_name":"비과세와 상품 비교","index":1,"title":"상품 기능별 차이점","definition":"저축·연금 상품은 세제, 운용 방식, 돈을 받는 형태와 계약 유지 조건을 나누어 비교해야 합니다.","explanation":["연금저축은 납입 단계의 세액공제와 수령 단계의 과세를 함께 살펴야 합니다. 다른 연금보험의 보험차익 비과세와 혼동하면 고객이 기대하는 세금 혜택과 실제 결과가 달라질 수 있습니다.","금리연동형은 적립에 적용하는 이율이 달라질 수 있고, 변액형은 특별계정의 운용실적을 반영합니다. 어느 방식이든 보험료에서 비용이 차감되는 구조와 해지 때 받을 돈을 함께 확인해야 합니다.","종신보험은 사망보장을 중심으로 하는 보험입니다. 연금전환이나 환급금 기능을 갖췄다는 이유만으로 처음부터 저축·연금 목적의 보험과 같은 상품으로 비교해서는 안 됩니다."],"practical":["가입 목적, 납입 여력, 사용할 시점, 수령 방법을 먼저 정리하고 각 기능이 그 목적에 맞는지를 확인합니다.","세제 요건과 계약 기능은 가입시기·상품에 따라 다릅니다. 상품명보다 비용, 해지 조건, 보증 범위, 수령 단계의 변화를 같은 기준으로 설명합니다."],"faq":[],"path":"articles/taxfree/02/"},{"id":"fire-basic-0","cat":"fire","cat_name":"화재보험","doc":"fire-basic","doc_name":"화재보험의 구조와 종류","index":0,"title":"화재보험의 의의","definition":"화재보험은 화재로 인한 재산 손해에 대비하기 위해 보장 대상과 조건을 정해 가입하는 보험입니다.","explanation":["보장받으려는 재산이 무엇인지부터 확인하고 계약에 기재된 대상과 일치하는지 살핍니다. 자신의 재산에 발생한 손해와 다른 사람에게 부담하는 배상책임은 서로 나누어 확인해야 합니다.","화재와 함께 발생한 손해라고 모두 같은 기준으로 보장되지는 않습니다. 화재 발생 시 생긴 도난이나 분실을 보상하지 않는 약관도 있으므로 손해의 발생 원인과 제외 항목을 확인합니다.","고의나 중대한 과실에 관한 제외 조항도 살펴야 합니다. 사고가 있었다는 사실 외에 어떤 경위로 발생했는지가 중요하며, 구체적인 보장 범위와 제외사항은 가입시기·상품에 따라 다릅니다."],"practical":["주택이나 사업장에서 보장하려는 재산을 정리하고, 재산 손해와 배상책임 중 어떤 위험에 대비하려는지 구분합니다.","사고가 나면 피해 대상과 발생 경위를 기록하고, 화재 자체 손해와 그 과정에서 발생한 다른 손해를 나누어 확인합니다."],"faq":[],"path":"articles/fire-basic/01/"},{"id":"fire-basic-1","cat":"fire","cat_name":"화재보험","doc":"fire-basic","doc_name":"화재보험의 구조와 종류","index":1,"title":"화재보험의 구조 및 종류","definition":"화재보험의 구조와 종류는 보장할 재산과 위험, 가입한 기본계약 및 특약을 나누어 살피는 내용입니다.","explanation":["재산을 보장하는 계약 안에 배상책임 특약이 구성되는 경우에도 각각의 지급사유는 별도로 정해집니다. 건물 자체의 손해와 화재로 사람이 다쳐 발생한 법률상 배상책임을 같은 항목으로 취급하지 않습니다.","특정한 건물을 대상으로 소유자의 화재 배상책임을 보장하는 특약도 있습니다. 이때는 건물이 계약에서 정한 대상에 해당하는지와 피보험자가 어떤 책임을 부담하는지를 확인해야 합니다.","일상생활배상책임 중에도 주택 내 화재와 폭발을 제외하는 형태가 있습니다. 비슷한 이름의 담보가 있어도 화재 위험이 자동으로 포함되는 것은 아니며, 보장 조건은 가입시기·상품에 따라 다릅니다."],"practical":["현재 증권에서 재산 관련 담보와 배상책임 담보를 구분한 뒤 대상 건물과 피보험자를 확인합니다.","특약의 포함·제외 항목을 비교하고, 고객이 보장된다고 생각하는 위험이 실제 가입 범위에 들어가는지 점검합니다."],"faq":[],"path":"articles/fire-basic/02/"},{"id":"fire-cover-0","cat":"fire","cat_name":"화재보험","doc":"fire-cover","doc_name":"화재보험 담보구성","index":0,"title":"화재보험의 담보 구성","definition":"화재보험 담보 구성은 어떤 재산의 어떤 손해를 보장할지 항목별로 확인하는 과정입니다.","explanation":["먼저 계약에 기재된 재산과 가입 담보를 대조합니다. 자신의 재산 피해와 타인에게 부담하는 배상책임을 구분하고 각각의 대상 및 지급 조건을 확인합니다.","특정 건물의 화재 배상책임 특약에는 법률상 손해배상금 외에 손해를 줄이기 위한 비용이나 권리를 지키기 위한 비용, 소송 관련 비용을 정한 경우가 있습니다. 이러한 비용이 모든 화재 담보에 공통으로 포함되는 것은 아닙니다.","배상책임 담보에도 주택 내 화재·폭발을 제외하는 형태가 있으므로 가입 여부와 제외 조항을 함께 봅니다. 비용 항목과 보장 한도, 적용 조건은 가입시기·상품에 따라 다릅니다."],"practical":["대상 재산, 손해 유형, 가입금액을 같은 순서로 정리하고 화재 관련 배상책임이 포함되는지 점검합니다.","사고 후에는 손상된 재산과 배상해야 할 손해, 지출 비용을 구분하고 각 비용의 목적을 확인할 자료를 남깁니다."],"faq":[],"path":"articles/fire-cover/01/"},{"id":"auto-cover-0","cat":"auto","cat_name":"자동차보험","doc":"auto-cover","doc_name":"대인 · 대물 · 자손/자상","index":0,"title":"대인배상","definition":"대인배상은 자동차 사고로 다른 사람이 다치거나 사망하여 피보험자가 부담하는 법률상 배상책임을 보장합니다.","explanation":["자동차보험에는 다른 사람에게 끼친 피해를 배상하는 담보와 본인의 손해를 보장하는 담보가 함께 구성됩니다. 대인배상은 상대방의 신체 피해에 대한 책임을 다루므로 운전자 자신의 부상 보장과 구분합니다.","대인배상은 의무적으로 가입하는 기본 보장과 그 범위를 넘는 책임을 대비하는 보장으로 구분하여 확인합니다. 가입 여부와 한도는 각각 확인해야 하며, 자동차보험에 가입했다는 사실만으로 충분한 범위가 확보되었다고 볼 수 없습니다.","누가 피보험자인지, 피해자가 해당 담보에서 보호하는 다른 사람에 해당하는지에 따라 검토 내용이 달라집니다. 같은 차량에 탑승했다고 해서 모든 사람의 보상 관계가 같다고 단정하지 않습니다."],"practical":["설계 단계에서 대인배상의 구분별 가입금액과 피보험자 범위를 확인하고, 본인의 부상 담보도 별도로 점검합니다.","사고 시에는 운전자, 차량을 사용한 관계, 피해자의 지위를 구분해 기록합니다. 구체적인 보상 범위는 가입시기·상품에 따라 다릅니다."],"faq":[],"path":"articles/auto-cover/01/"},{"id":"auto-cover-1","cat":"auto","cat_name":"자동차보험","doc":"auto-cover","doc_name":"대인 · 대물 · 자손/자상","index":1,"title":"대물배상","definition":"대물배상은 자동차 사고로 다른 사람의 재물을 훼손하여 생긴 법률상 손해배상책임을 보장합니다.","explanation":["보상 대상은 상대 차량에만 한정된다고 생각하기 쉽지만, 다른 사람의 건물이나 물건에 대한 손해도 약관상 요건에 해당하는지 검토합니다. 핵심은 피보험자동차의 사고와 타인의 재물 손해 사이의 관계입니다.","자기 차량의 파손을 보장하는 담보와 대물배상은 다릅니다. 내 차와 상대방 재물에 모두 손상이 생긴 사고라면 어떤 손해를 어느 담보로 처리하는지 구분해야 합니다.","사고가 주행 중에만 발생하는 것은 아닙니다. 자동차를 소유·사용·관리하는 과정에서 생긴 사고도 약관의 문구와 구체적인 경위에 따라 검토되므로, 정차 중이라는 이유만으로 보상 여부를 단정하지 않습니다."],"practical":["가입금액과 배상책임의 범위를 확인하고, 피해 차량 외에 함께 손상된 시설물이나 재물이 있는지도 살펴봅니다.","사고 발생 과정, 손상된 대상, 배상 요구 내용을 분리해 정리합니다. 세부 지급기준과 보상에서 제외되는 사항은 가입시기·상품에 따라 다릅니다."],"faq":[],"path":"articles/auto-cover/02/"},{"id":"auto-cover-2","cat":"auto","cat_name":"자동차보험","doc":"auto-cover","doc_name":"대인 · 대물 · 자손/자상","index":2,"title":"자기신체사고와 자동차상해의 차이","definition":"자기신체사고와 자동차상해는 자동차 사고로 피보험자가 다친 경우를 다루며 보상 기준을 구분해 확인해야 하는 담보입니다.","explanation":["다른 사람에 대한 배상책임 담보와 본인의 신체 손해를 다루는 담보는 역할이 다릅니다. 먼저 사고를 당한 사람이 해당 담보의 피보험자에 포함되는지를 확인합니다.","비교할 때는 가입금액뿐 아니라 부상 시 지급한도와 치료비 등 인정되는 항목을 함께 살펴야 합니다. 담보 이름만으로 지급금액이 같거나 항상 더 크다고 단정하지 않습니다.","사망·후유장해·부상의 기준을 각각 구분하고, 자기신체사고의 기본 조건과 자동차상해 특약의 추가 조건을 대조합니다. 세부 범위는 가입시기·상품에 따라 다릅니다."],"practical":["실제 가입한 담보와 한도를 보험증권에서 확인하고 적용되는 지급기준을 설명합니다.","사고 경위와 상해 내용, 치료비 자료를 정리한 뒤 해당 계약의 산정 방식으로 검토합니다."],"faq":[],"path":"articles/auto-cover/03/"},{"id":"auto-terms-0","cat":"auto","cat_name":"자동차보험","doc":"auto-terms","doc_name":"자동차보험 약관과 특약","index":0,"title":"자동차보험 약관","definition":"자동차보험 약관은 사고별 보장 대상과 지급기준, 운전자 조건과 계약 변경 절차를 정하는 기준입니다.","explanation":["먼저 다른 사람에 대한 배상책임과 본인의 신체·차량 손해를 나누어 읽습니다. 비슷한 사고라도 담보별로 피보험자와 보상책임이 발생하는 조건이 다를 수 있습니다.","보통약관에 기본 보장이 적혀 있고, 특약에서는 보장 확대나 운전자 범위 제한 등 추가 조건을 정합니다. 특약 이름만 읽기보다 적용 대상과 보상하지 않는 경우를 함께 확인해야 합니다.","운전자 범위와 연령 조건은 실제 사고 운전자에게 적용되는지 확인합니다. 가족이라는 일상적인 표현과 특약에서 정한 가족의 범위가 같다고 단정하면 보장 공백이 생길 수 있습니다."],"practical":["가입한 담보, 보험기간, 차량 정보, 운전자 범위와 연령을 보험증권과 대조합니다. 입력한 정보가 고객의 실제 운전 상황과 맞는지 확인합니다.","보험금 판단에서는 해당 사고에 적용되는 담보의 정의부터 읽습니다. 세부 조건은 가입시기·상품에 따라 다르므로 다른 담보의 요건을 섞어 적용하지 않습니다."],"faq":[],"path":"articles/auto-terms/01/"},{"id":"auto-terms-1","cat":"auto","cat_name":"자동차보험","doc":"auto-terms","doc_name":"자동차보험 약관과 특약","index":1,"title":"추가 가능한 특약과 가입 팁","definition":"자동차보험 특약은 운전 환경에 맞게 보장 범위를 조정하거나 할인과 부가 서비스를 적용하는 계약 조건입니다.","explanation":["특약에는 보장을 확대하는 기능과 보험료를 조정하는 기능이 있습니다. 다른 자동차 운전, 긴급출동, 주행거리 등 이름이 비슷해도 적용 대상과 조건을 각각 확인해야 합니다.","운전자 한정과 연령 한정은 실제로 운전할 사람을 기준으로 설정합니다. 생년월일이나 관계를 잘못 전달하면 고객의 의도와 다른 조건으로 계약될 수 있으므로 청약 단계의 정보 확인이 중요합니다.","주행거리 특약은 계약에서 정한 정산 방식을 확인해야 합니다. 먼저 할인받는 방식에서는 실제 주행거리가 약정 범위를 넘으면 추가보험료가 생길 수 있으므로 할인 결과만 안내하지 않습니다."],"practical":["운전자의 범위, 평소 운행 모습, 필요로 하는 서비스를 확인한 뒤 해당 특약의 대상에 맞는지 검토합니다.","가입 이후에도 보험증권의 운전자 조건과 선택한 특약을 다시 확인합니다. 가입시기·상품에 따라 특약의 제공 여부와 정산 방식이 다릅니다."],"faq":[],"path":"articles/auto-terms/02/"},{"id":"law-0","cat":"terms","cat_name":"약관","doc":"law","doc_name":"상법과 보험업법","index":0,"title":"상법 보험편과 보험업법의 역할","definition":"상법의 보험 규정과 보험업법은 보험계약의 책임과 보험 모집·업무에 관한 판단에 함께 쓰이는 법적 기준입니다.","explanation":["상법의 보험 규정은 보험료 납입과 보험자의 책임개시처럼 계약 당사자 사이의 관계를 판단할 때 사용됩니다. 실제 보장개시를 확인할 때에는 적용 법규와 계약의 약정을 함께 살펴야 합니다.","보험업법은 보험 모집 과정에서 생긴 손해의 배상책임 등 보험업무와 관련된 문제에도 적용됩니다. 보험금 지급책임이 있는지와 모집 과정의 잘못으로 손해배상책임이 있는지는 서로 다른 쟁점일 수 있습니다.","사례에서는 계약 변경 요청을 받았는지뿐 아니라 추가보험료 납입과 변경 절차 안내가 제대로 이루어졌는지도 검토됩니다. 법률 이름만 확인하기보다 문제 되는 행위와 책임을 구분하는 것이 중요합니다."],"practical":["상담 내용을 계약의 성립, 보장개시, 보험금 지급, 모집 과정의 손해 문제로 나누어 확인합니다.","법령의 적용과 결론은 구체적인 계약과 사실관계에 따라 달라질 수 있습니다. 확인된 절차와 안내 내용을 기록하고 개별 분쟁의 결과를 미리 단정하지 않습니다."],"faq":[],"path":"articles/law/01/"},{"id":"general-0","cat":"terms","cat_name":"약관","doc":"general","doc_name":"보통약관","index":0,"title":"부담보","definition":"부담보는 계약을 인수하면서 특정 질병 등 정해진 부분의 보장을 제외하는 조건입니다.","explanation":["가입이 승인되었다는 사실과 모든 위험을 제한 없이 보장한다는 뜻은 다릅니다. 일부 보장 제외 조건을 붙여 계약을 받는 경우에는 제외 대상이 무엇인지 따로 확인해야 합니다.","제외 범위와 적용기간을 나누어 살펴야 합니다. 고객이 알고 있는 질병 이름과 실제 계약에 적힌 범위가 일치하는지 확인하고, 비슷한 증상을 임의로 같은 조건에 포함시키거나 제외하지 않습니다.","일정 기간 추가 진단이나 치료가 없을 때 보장 제외 조건의 적용이 달라지는 계약도 있습니다. 다만 모든 부담보가 시간만 지나면 자동 해제된다고 설명하면 안 되며, 계약의 유지와 부활 이력도 함께 확인해야 합니다."],"practical":["인수 결과에서 제외 대상, 기간과 적용 담보를 고객과 확인하고 보장받을 수 있는 나머지 범위도 구분해 안내합니다.","조건의 종료나 변경은 해당 계약의 규정에 따라 확인합니다. 가입시기·상품에 따라 기준이 다르므로 다른 계약의 해제 사례를 그대로 적용하지 않습니다."],"faq":[],"path":"articles/general/01/"},{"id":"general-1","cat":"terms","cat_name":"약관","doc":"general","doc_name":"보통약관","index":1,"title":"실효와 부활","definition":"실효와 부활은 보험료 연체로 계약이 해지된 상태와 일정한 조건 아래 그 효력을 회복하는 절차를 가리킵니다.","explanation":["보험료가 연체되면 납입최고와 계약 해지에 관한 규정에 따라 처리됩니다. 납입하지 않은 사실만 확인할 것이 아니라 실제로 계약이 어떤 상태인지, 안내된 납입기한이 언제인지 살펴야 합니다.","해지된 계약은 해약환급금 수령 여부와 정해진 신청기간 등 조건을 충족하면 부활을 청약할 수 있습니다. 신청만으로 바로 보장이 회복되는 것은 아니며 회사가 정한 절차와 승낙 여부를 확인해야 합니다.","부활 때는 연체 보험료와 약정한 이자 납입, 계약 전 알릴 의무가 적용될 수 있습니다. 담보에 따라 보장개시 조건을 다시 적용하는 경우도 있어 과거 계약이 아무 변화 없이 이어진다고 설명하지 않습니다."],"practical":["해지 사유와 날짜, 환급금 수령 여부, 부활 신청 가능 여부를 먼저 확인합니다. 적용 조건은 가입시기·상품에 따라 다릅니다.","부활을 처리한 뒤에는 효력 회복일과 담보별 보장개시일을 확인하여 고객에게 안내합니다. 과거 고지의무 위반 문제도 부활로 자동 해소되는 것은 아닙니다."],"faq":[],"path":"articles/general/02/"},{"id":"general-2","cat":"terms","cat_name":"약관","doc":"general","doc_name":"보통약관","index":2,"title":"납입면제","definition":"납입면제는 약정한 질병이나 장해 등 정해진 사유가 생기면 이후 보험료 납입을 면제하는 기능입니다.","explanation":["보험금을 지급받는 조건과 납입면제 조건은 따로 확인해야 합니다. 치료를 받거나 보험금을 받았다는 사실만으로 남은 보험료가 모두 면제된다고 볼 수 없습니다.","어떤 질병이나 장해를 인정하는지, 어느 시점 이후의 보험료를 면제하는지와 적용 대상 보험료를 살펴야 합니다. 납입면제가 없는 유형도 있으며 주계약과 특약의 적용 범위가 다를 수 있습니다.","납입면제와 납입완료는 같은 의미가 아닙니다. 면제를 받았더라도 원래 납입기간 중 해지하면 환급금이 없는 구조가 있어, 면제 승인만으로 해지 때 돌려받는 돈이 늘어난다고 설명하지 않습니다."],"practical":["면제 사유를 확인할 때는 질병 진단이나 장해 상태를 입증하는 자료와 담보별 적용 조건을 함께 점검합니다.","승인 후에는 어느 보험료가 언제부터 면제되는지 확인하여 안내합니다. 가입시기·상품에 따라 조건이 다르므로 면제되지 않는 부분의 납입 여부도 따로 살펴봅니다."],"faq":[],"path":"articles/general/03/"},{"id":"general-3","cat":"terms","cat_name":"약관","doc":"general","doc_name":"보통약관","index":3,"title":"청약철회","definition":"청약철회는 정해진 기간과 요건 안에서 계약자가 보험 가입 의사를 철회하는 제도입니다.","explanation":["가능 기간은 보험증권을 받은 날을 기준으로 하는 기간과 청약한 날부터의 한도를 함께 확인합니다. 전화로 가입한 계약이나 계약자 조건 등에 따라 규정이 달라질 수 있어 날짜를 하나만 확인해서는 안 됩니다.","건강상태 진단을 지원하는 계약, 짧은 보험기간의 계약 등 철회가 제한되는 경우가 있습니다. 가입한 계약의 대상 여부를 먼저 확인하고 일반적인 설명을 모든 계약에 적용하지 않습니다.","철회 의사는 계약에서 인정하는 전화나 서면·전자적 방법 등으로 표시할 수 있습니다. 접수 이후에는 납입보험료 반환이나 카드 결제 취소가 정상 처리되었는지도 확인해야 합니다."],"practical":["청약일, 보험증권 수령일과 신청일을 구분해 기록합니다. 청약철회와 중도해지는 반환되는 돈의 구조가 다를 수 있으므로 요청 내용을 정확히 확인합니다.","보험금 지급사유가 이미 발생한 경우에는 철회의 효력이 달라질 수 있습니다. 가입시기·상품에 따른 예외와 처리 기준을 함께 확인합니다."],"faq":[],"path":"articles/general/04/"},{"id":"general-4","cat":"terms","cat_name":"약관","doc":"general","doc_name":"보통약관","index":4,"title":"계약 전 알릴 의무","definition":"계약 전 알릴 의무는 보험 가입을 심사하는 데 필요한 질문에 계약자와 피보험자가 사실대로 답해야 하는 의무입니다.","explanation":["질문은 가입을 거절하거나 보장 제외·보험료 할증 같은 조건을 붙일지 판단하는 자료가 됩니다. 고객이 중요하지 않다고 생각하는 내용도 질문 범위에 해당하면 임의로 빼지 않도록 안내해야 합니다.","질문의 대상기간과 행위를 나누어 확인합니다. 진단, 치료, 입원, 수술, 투약, 추가검사 등은 질문별로 범위가 다르므로 단순히 건강한지 묻는 방식으로 대신하지 않습니다.","고지의무 위반이 문제 된 경우에는 계약 해지 여부와 이미 발생한 보험사고의 지급 여부를 구분해야 합니다. 알리지 않은 사실과 사고 사이의 관계 등 구체적인 조건에 따라 결론이 달라질 수 있습니다."],"practical":["실제 청약서의 질문을 고객과 확인하고 답변을 정확히 기재하도록 돕습니다. 질문 내용과 기준은 가입시기·상품에 따라 다릅니다.","설계사가 고지할 기회를 막거나 사실과 다르게 답하도록 유도하지 않습니다. 기억이 불확실한 진료나 검사 이력은 확인 후 답할 수 있도록 안내합니다."],"faq":[],"path":"articles/general/05/"},{"id":"special-0","cat":"terms","cat_name":"약관","doc":"special","doc_name":"특별약관","index":0,"title":"특별약관의 구조","definition":"특별약관은 기본 계약에 보장을 더하거나 적용 조건과 절차를 따로 정하기 위해 붙이는 약정입니다.","explanation":["특약에는 보험금을 지급하는 보장 특약뿐 아니라 전자서명이나 계약 처리 방식 등을 정하는 제도성 특약도 있습니다. 이름에 특약이 붙었다고 해서 모두 추가 보험금을 지급하는 것은 아닙니다.","보장 특약은 지급사유, 질병의 정의, 지급금액, 보장개시일과 소멸 조건 등을 따로 정할 수 있습니다. 주계약을 읽었다고 해서 가입한 모든 특약의 지급 조건까지 확인한 것으로 볼 수 없습니다.","특약에서 정하지 않은 내용은 보통약관을 따르도록 하는 준용규정이 있습니다. 다만 적용하지 않는 조항을 별도로 적은 경우가 있으므로 단순히 모든 보통약관 규정이 동일하게 적용된다고 가정하지 않습니다."],"practical":["보험증권에 기재된 가입 특약을 목록으로 확인하고, 특약별 보험기간과 갱신 여부를 따로 살펴봅니다.","지급사유와 제외 조건을 읽은 뒤 마지막의 준용규정까지 확인합니다. 가입시기·상품에 따라 같은 이름의 특약도 조건이 달라질 수 있습니다."],"faq":[],"path":"articles/special/01/"},{"id":"dispute-0","cat":"terms","cat_name":"약관","doc":"dispute","doc_name":"분쟁사례와 판례","index":0,"title":"분쟁사례 및 판례 정리","definition":"보험 분쟁사례는 사고 사실과 약관의 적용이 어떻게 검토되는지 배우는 자료이며, 결과만으로 다른 계약의 지급을 확정할 수는 없습니다.","explanation":["같은 병명이나 사고 이름이 등장해도 적용 약관, 사고 경위와 확인된 자료가 다르면 판단이 달라질 수 있습니다. 먼저 어떤 사실에 다툼이 있었고 어떤 조항이 쟁점이었는지 구분해야 합니다.","상해사망에서는 외부 사고가 있었는지와 그 사고가 사망에 영향을 주었는지가 따로 검토됩니다. 질병과 사고가 함께 작용한 사례에서는 진료기록과 의학적 의견 등 여러 자료를 종합합니다.","고지의무 분쟁에서는 계약을 해지할 수 있는지와 보험금을 지급해야 하는지가 다른 문제일 수 있습니다. 어떤 보험금이 지급되었다는 결과만으로 계약 해지까지 불가능하다고 단정하면 안 됩니다."],"practical":["사례를 읽을 때는 적용 조건, 확인된 사실, 판단 이유를 정리하고 현재 상담 건과 같은 부분과 다른 부분을 구분합니다.","고객에게는 확인된 약관 문구와 필요한 자료를 안내합니다. 다른 사람의 지급 사례를 근거로 보험금 지급을 약속하지 않고 해당 계약의 심사 결과를 확인합니다."],"faq":[],"path":"articles/dispute/01/"},{"id":"disclosure-0","cat":"goji","cat_name":"고지의무·보상","doc":"disclosure","doc_name":"고지의무 (일반 · 간편)","index":0,"title":"계약 전 알릴 의무란","definition":"계약 전 알릴 의무는 청약할 때 회사가 질문한 중요한 사항에 관해 알고 있는 사실을 정확히 알리는 의무입니다.","explanation":["보험회사는 건강상태와 직업 등 질문에 대한 답변을 바탕으로 계약을 받아들일지, 보장에 별도 조건을 붙일지를 판단합니다. 고객이 가볍게 여기는 치료라도 질문 범위에 해당하면 답변에 반영해야 합니다.","알리는 대상은 설계사 개인이 아니라 계약을 심사하는 보험회사입니다. 설계사에게 말로만 설명했다면 청약서나 정해진 고지 절차에 사실이 기록되었는지 다시 확인해야 합니다.","질문은 상품과 심사유형에 따라 달라집니다. 과거에 작성한 답변을 그대로 옮기지 말고 이번 청약에서 묻는 질병, 의료행위, 기간을 각각 읽어야 합니다.","중요한 사실을 알리지 않거나 다르게 알리면 계약 해지나 보장 제한으로 이어질 수 있습니다. 다만 위반 여부와 처리 결과는 실제 질문, 답변, 설명 경위 및 해당 계약 조건에 따라 판단합니다."],"practical":["고객이 직접 질문과 답변을 확인하도록 하고, 구두로 들은 병력도 정해진 입력란에 반영되었는지 대조합니다.","기억이 불확실한 치료일이나 검사 내용은 추측해 적지 말고 진료기록 등으로 확인한 뒤 고지합니다."],"faq":[],"path":"articles/disclosure/01/"},{"id":"disclosure-1","cat":"goji","cat_name":"고지의무·보상","doc":"disclosure","doc_name":"고지의무 (일반 · 간편)","index":1,"title":"일반심사 고지 항목","definition":"일반심사 고지는 청약서가 정한 기간 안의 진단·치료 이력과 직업 등 위험 관련 사항을 확인하는 절차입니다.","explanation":["질문에는 질병 확정진단뿐 아니라 의심소견, 검사, 입원, 수술, 치료, 투약 등이 포함될 수 있습니다. 진단명이 없었다는 이유만으로 모든 질문에 해당하지 않는다고 판단하면 안 됩니다.","최근의 의료행위와 더 긴 기간의 입원·수술·지속적인 치료를 따로 묻기도 합니다. 질문마다 확인 기간과 의료행위 범위가 다르므로 한 질문의 답변으로 나머지 질문을 대신하지 않습니다.","추가검사를 실제로 받았는지와 검사가 필요하다는 소견을 받았는지는 서로 다른 내용입니다. 해당 청약서의 표현을 읽고 어느 사실을 묻는지 구분해야 합니다.","건강정보 외에도 직업과 구체적인 업무, 운전 여부 등을 확인할 수 있습니다. 질문 항목과 세부 기준은 가입시기·상품에 따라 다르며 선택한 특약에 추가 질문이 붙을 수 있습니다."],"practical":["병력은 질병명, 치료기간, 치료방법, 재발 및 현재 상태를 나누어 정리한 뒤 질문과 대조합니다.","직업명만 쓰지 말고 실제 수행하는 업무와 운전 형태가 질문 내용에 맞게 기록되었는지 확인합니다."],"faq":[],"path":"articles/disclosure/02/"},{"id":"disclosure-2","cat":"goji","cat_name":"고지의무·보상","doc":"disclosure","doc_name":"고지의무 (일반 · 간편)","index":2,"title":"간편고지(3·2·5)","definition":"간편고지는 일반심사와 다른 질문 체계로 건강상태를 확인하는 방식이며 고지 자체가 없어지는 것은 아닙니다.","explanation":["간편심사를 나타내는 약칭은 질문 기간을 줄여 표현한 경우가 있지만 약칭만으로 고지 범위를 확정할 수 없습니다. 실제로 묻는 진단, 필요 소견, 입원, 수술의 범위를 질문 문장별로 읽어야 합니다.","가까운 시기의 입원·수술·추가검사 필요 소견을 묻거나 과거 입원·수술 이력을 따로 묻는 구조가 있습니다. 실제 검사를 받지 않았더라도 필요 소견이 질문에 포함되는지 확인합니다.","중대한 질병을 따로 묻는 질문도 상품에 따라 암만 확인하거나 다른 질병까지 포함합니다. 선택한 보장에 치매나 장기요양 관련 추가 질문이 있을 수도 있습니다.","같은 간편심사라는 이름이라도 질문 기간과 예외 설명은 가입시기·상품에 따라 다릅니다. 다른 계약에서 가입이 가능했다는 사실만으로 이번 계약의 고지나 승낙을 대신할 수 없습니다."],"practical":["간편심사 유형의 숫자보다 청약서의 실제 질문과 주석을 먼저 확인합니다.","입원·수술 여부와 의사의 필요 소견을 별도로 정리하고, 추가 질문까지 고객이 직접 확인하도록 합니다."],"faq":[],"path":"articles/disclosure/03/"},{"id":"disclosure-3","cat":"goji","cat_name":"고지의무·보상","doc":"disclosure","doc_name":"고지의무 (일반 · 간편)","index":3,"title":"위반 시 처리와 해지 제한","definition":"고지의무 위반 처리는 계약을 유지할 수 있는지와 발생한 사고의 보험금을 지급하는지를 나누어 판단하는 절차입니다.","explanation":["회사가 청약을 받아들일지 또는 별도 조건을 붙일지에 영향을 주는 사실은 중요한 사항이 될 수 있습니다. 답변과 실제 사실이 다르면 고의 또는 중대한 과실이 있었는지 등 해지 요건을 확인해야 합니다.","고지의무 위반을 이유로 계약을 해지하는 판단과 보험금 지급 판단은 항상 같지 않습니다. 알리지 않은 사실과 사고 사이에 관련이 없는 경우에도 계약 해지 문제가 남을 수 있습니다.","반대로 설계사가 고지할 기회를 주지 않거나 사실대로 알리는 것을 방해한 경우에는 해지나 보장 제한이 제한될 수 있습니다. 고객의 답변만 보지 말고 모집 과정에서 있었던 설명과 행위도 함께 살펴야 합니다.","회사가 이미 사실을 알았거나 중대한 과실로 알지 못한 경우에는 해지가 제한됩니다. 해지권을 행사할 수 있는 기간에도 제한이 있으므로 위반을 알게 된 시점과 계약 체결 시점을 함께 확인합니다.","보험금을 이미 받았다고 계약 해지 가능성이 자동으로 사라지는 것도 아닙니다. 처리 통지를 받았다면 적용한 질문, 위반으로 본 사실, 해지 근거와 지급 판단의 이유를 각각 확인해야 합니다."],"practical":["청약 당시 질문과 답변, 설명 및 보완 기록을 확보하여 현재의 진료기록과 대조합니다.","해지 통지와 보험금 심사 결과를 분리해 읽고, 다투는 내용이 무엇인지 서면으로 정리합니다."],"faq":[],"path":"articles/disclosure/04/"},{"id":"disclosure-4","cat":"goji","cat_name":"고지의무·보상","doc":"disclosure","doc_name":"고지의무 (일반 · 간편)","index":4,"title":"실무 체크포인트","definition":"고지 실무의 핵심은 고객이 알고 있는 사실을 질문에 맞추어 빠짐없이 기록하고 최종 답변을 확인하는 데 있습니다.","explanation":["상담 중에 들은 병력과 청약서에 입력한 내용은 일치해야 합니다. 구두 설명이 있었다는 사실만으로 고지가 완료되는 것은 아니므로 제출되는 답변을 고객과 함께 확인합니다.","질병명만으로는 질문에 답하기 어려운 경우가 있습니다. 진단과 검사, 입원과 통원, 수술과 투약을 구분하고 각각의 시점과 현재 상태를 정리하면 빠진 내용을 찾기 쉽습니다.","의심소견이나 추가검사에 관한 질문에는 별도의 정의가 붙을 수 있습니다. 정기적인 관찰인지 이상소견에 따른 검사인지 등을 스스로 단정하지 말고 실제 질문의 설명과 진료 내용을 대조합니다.","상품이나 특약이 달라지면 질문도 바뀔 수 있습니다. 이전 청약의 답변을 그대로 복사하지 않고 새 질문과 확인 기간에 맞추어 다시 점검하는 절차가 필요합니다."],"practical":["날짜가 불명확하거나 의료행위의 성격이 애매하면 확인할 자료와 추가 질문을 먼저 정리합니다.","제출 전에는 고객이 질문과 최종 답변을 직접 읽도록 하고, 수정한 내용이 제출본에도 반영되었는지 확인합니다.","고지 여부가 인수에 불리해 보인다는 이유로 답변을 생략하거나 표현을 바꾸도록 유도하지 않습니다."],"faq":[],"path":"articles/disclosure/05/"},{"id":"claim-0","cat":"goji","cat_name":"고지의무·보상","doc":"claim","doc_name":"보험금 청구 절차","index":0,"title":"보험금 청구 및 절차","definition":"보험금 청구는 보험수익자가 사고와 치료 사실을 확인할 서류를 제출하고 계약에 따른 지급 심사를 요청하는 절차입니다.","explanation":["먼저 가입한 담보에서 어떤 사고나 치료를 보장하는지 확인합니다. 같은 진료라도 진단비, 입원비, 수술비, 실손의료비가 요구하는 확인 내용과 준비서류는 서로 다를 수 있습니다.","청구서와 본인 확인 자료 외에 진단서, 입퇴원 확인서, 수술 확인서, 진료비 계산서나 세부내역서 등이 필요할 수 있습니다. 서류를 모두 미리 발급하기보다 해당 청구에 필요한 종류와 간소화 가능 여부를 확인합니다.","접수 후에는 보상 여부 검토와 필요한 사실조사를 거쳐 보험금이 결정됩니다. 추가서류나 방문조사가 필요한 경우가 있으므로 접수 사실과 담당 창구를 확인하고 보완 요청 내용을 정리합니다.","지급 결과와 지연 사유는 안내받아 확인합니다. 청구 방법, 서류, 지급기한과 조사 절차는 가입시기·상품 및 사고 내용에 따라 다르므로 한 계약의 안내를 모든 청구에 적용하지 않습니다."],"practical":["진단명과 치료 내용이 담보의 지급조건을 확인할 수 있을 만큼 서류에 기재되어 있는지 살핍니다.","대리 청구나 다른 사람의 계좌로 받는 경우에는 청구권자 확인과 위임 관련 서류를 별도로 점검합니다.","접수일, 추가 요청 자료, 지급 또는 부지급 안내를 구분하여 기록합니다."],"faq":[],"path":"articles/claim/01/"},{"id":"claim-1","cat":"goji","cat_name":"고지의무·보상","doc":"claim","doc_name":"보험금 청구 절차","index":1,"title":"고지의무 적용 방법과 보상","definition":"보상 단계의 고지 검토는 청약 당시 알린 사실과 보험사고의 관계를 확인하여 계약 및 지급에 미치는 영향을 판단하는 과정입니다.","explanation":["보험금 청구 과정에서 과거 병력이 확인되었다고 곧바로 모든 보험금이 지급되지 않는 것은 아닙니다. 먼저 당시 질문이 무엇이었는지, 고객이 어떤 사실을 알고 답했는지, 중요한 사항에 해당하는지를 확인합니다.","고지 누락 사실과 발생한 사고 사이의 관련성은 보험금 지급 판단에서 별도로 살펴야 합니다. 관련이 없는 사고에 보험금이 지급되더라도 계약의 해지 가능성은 따로 남을 수 있습니다.","회사에서 사실조사를 요청하면 조사 목적과 필요한 자료를 확인합니다. 약관은 서면 조사 요청과 목적 설명 등에 관한 절차를 두고 있으므로 막연한 구두 안내만으로 상황을 판단하지 않습니다.","설계사가 사실대로 알리는 것을 방해했는지와 같은 모집 경위도 확인 대상입니다. 상담 단계의 기억만으로 결론을 내리지 말고 청약 기록과 치료기록, 처리 통지를 함께 검토합니다."],"practical":["지급조건 충족 여부, 고지위반 여부, 사고와의 관련성을 나누어 쟁점을 정리합니다.","자료 보완 요청에는 어떤 사실을 확인하려는 것인지 확인하고 제출한 자료의 사본을 보관합니다.","고객에게 지급이나 해지를 미리 확정해 말하지 말고 회사의 판단 근거를 받아 설명합니다."],"faq":[],"path":"articles/claim/02/"},{"id":"benef-0","cat":"goji","cat_name":"고지의무·보상","doc":"benef","doc_name":"수익자 지정","index":0,"title":"수익자 지정 및 케이스","definition":"보험수익자는 약정된 보험금 지급사유가 발생했을 때 보험금을 받을 권리가 있는 사람입니다.","explanation":["보험료를 내는 계약자, 보장의 대상인 피보험자, 보험금을 받는 수익자는 같을 수도 있고 다를 수도 있습니다. 가족이라는 이유만으로 보험금을 받을 사람이 정해졌다고 보지 말고 실제 지정 내용을 확인합니다.","수익자를 따로 정하지 않으면 약관이 정한 기본 기준을 적용합니다. 사망보험금은 피보험자의 법정상속인, 그 밖의 보험금은 피보험자, 만기환급금은 계약자로 정한 구조가 있지만 담보별 규정을 확인해야 합니다.","사망보험금 수익자를 지정하거나 변경할 때 계약자와 피보험자가 다르면 피보험자의 서면동의 등 필요한 절차를 확인합니다. 단순히 요청을 전달한 것과 변경이 완료된 것은 구분해야 합니다.","지정된 수익자의 사망이나 계약자의 사망은 이후의 지정·변경 및 수령 관계에 영향을 줄 수 있습니다. 수익자 지정과 승계에 관한 조건은 가입시기·상품에 따라 다르므로 개별 계약을 기준으로 판단합니다."],"practical":["사망, 생존 중 지급되는 보험금, 만기환급금의 수익자를 각각 확인합니다.","가족관계나 지급 희망 대상이 달라졌다면 변경 가능 여부와 동의서류를 점검하고 처리 완료 내용을 확인합니다."],"faq":[],"path":"articles/benef/01/"},{"id":"renew-0","cat":"basics","cat_name":"상품 기초개념","doc":"renew","doc_name":"갱신형과 비갱신형","index":0,"title":"갱신형과 비갱신형의 구조","definition":"갱신형은 정해진 보험기간이 끝날 때 계약을 갱신하는 구조이고, 비갱신형은 처음 정한 기간과 납입조건으로 보장하는 구조입니다.","explanation":["갱신형 계약은 갱신 시점의 나이와 위험률 변동 등에 따라 보험료가 달라질 수 있습니다. 최초 보험료를 계속 낸다고 생각하지 않도록 갱신 주기와 이후 보험료 납입을 함께 설명해야 합니다.","비갱신형은 갱신을 전제로 보험료를 다시 산정하지 않는 구조입니다. 다만 실제 납입조건은 계약에서 정한 방식에 따르므로 비갱신이라는 말만 듣고 모든 시점의 납입액이 같다고 단정하지 않습니다.","주계약과 특약은 갱신 여부가 서로 다를 수 있습니다. 주계약의 납입이 끝났어도 갱신형 특약에는 보험료 납입이 이어질 수 있으므로 계약 전체와 담보별 조건을 나누어 봅니다.","갱신 가능한 최종 시점과 마지막 갱신계약의 기간은 상품별로 다릅니다. 가입시기·상품에 따라 다른 조건을 확인하고 필요한 보장 기간 동안 어떻게 유지되는지 설명합니다."],"practical":["설계 내용에서 담보별 갱신 여부, 갱신 주기, 최종 보장 시점을 표시합니다.","보험료 납입이 끝나는 시점과 보장이 끝나는 시점을 따로 설명하고 갱신형 특약의 계속 납입 여부를 확인합니다."],"faq":[],"path":"articles/renew/01/"},{"id":"renew-1","cat":"basics","cat_name":"상품 기초개념","doc":"renew","doc_name":"갱신형과 비갱신형","index":1,"title":"보험료 비교 시 주의점","definition":"보험료는 보장 내용과 유지 조건을 함께 보아야 의미 있게 판단할 수 있는 계약 비용입니다.","explanation":["처음 내는 금액만으로 갱신형과 비갱신형의 부담을 판단하기 어렵습니다. 갱신형에는 나이 증가와 위험률 변동에 따른 보험료 변화가 있으므로 최초 보험료와 미래 보험료를 구분해야 합니다.","보험기간과 납입기간이 다르면 같은 월 납입액도 의미가 달라집니다. 보장을 받는 기간과 돈을 내는 기간을 먼저 확인한 뒤 주계약과 특약에 별도 납입이 남는지 살펴야 합니다.","해약환급금을 줄이거나 지급하지 않는 대신 보험료를 낮춘 구조도 있습니다. 낮은 보험료가 어떤 해지 조건과 연결되어 있는지 확인하지 않으면 중도해지 시 받을 금액을 잘못 예상할 수 있습니다.","만기환급금이 없는 보장형과 환급 기능을 둔 형태 역시 목적이 다릅니다. 가입시기·상품에 따라 달라지는 갱신, 환급, 보장기간을 확인하여 비용과 함께 설명합니다."],"practical":["가입금액과 보장기간, 납입기간, 갱신 및 환급 조건을 같은 순서로 정리합니다.","미래 보험료 예시는 확정액과 구분하고, 현재 납입액을 단순 연장한 계산으로 총부담을 확정하지 않습니다.","월 보험료뿐 아니라 중도해지 시 받을 금액도 함께 확인합니다."],"faq":[],"path":"articles/renew/02/"},{"id":"refund-0","cat":"basics","cat_name":"상품 기초개념","doc":"refund","doc_name":"환급형과 순수보장형","index":0,"title":"환급형과 순수보장형","definition":"만기환급형과 순수보장형은 계약을 만기까지 유지했을 때 돌려받는 금액이 있는지로 구분하는 구조입니다.","explanation":["만기환급형은 계약에서 정한 조건을 충족해 만기에 도달했을 때 환급금이 지급되는 형태입니다. 돌려받는 금액이 있다는 뜻이지 납입보험료 전부를 반드시 돌려받는다는 뜻은 아닙니다.","순수보장형은 보장에 필요한 비용을 내고 약정한 위험에 대비하는 형태로, 만기환급금이 없는 구조입니다. 보험사고 없이 만기가 되었다고 낸 보험료를 돌려달라고 청구할 수 있는 것은 아닙니다.","만기환급금과 중도해지 때의 해약환급금은 서로 다른 항목입니다. 만기환급금이 없다는 설명만으로 어느 시점에도 해약환급금이 없다고 이해해서는 안 됩니다.","주계약에 환급 기능이 있더라도 모든 특약에 같은 기능이 있는 것은 아닙니다. 환급 여부와 계산방식은 가입시기·상품에 따라 다르므로 주계약과 특약의 조건을 구분해 확인합니다."],"practical":["만기에 지급되는 금액과 중도해지 시의 금액을 각각 확인하고 고객이 혼동하지 않도록 설명합니다.","환급 기능을 선택할 때에는 보장 내용과 납입 부담도 함께 확인하여 유지 목적에 맞는지 살핍니다."],"faq":[],"path":"articles/refund/01/"},{"id":"refund-1","cat":"basics","cat_name":"상품 기초개념","doc":"refund","doc_name":"환급형과 순수보장형","index":1,"title":"적립보험료의 의미","definition":"적립보험료는 납입보험료 중 적립 부분에 해당하는 금액으로, 그 전액이 그대로 적립되는 것은 아닙니다.","explanation":["보험료를 보장보험료와 적립보험료로 구분하는 상품에서는 보장에 쓰이는 부분과 환급금 형성에 쓰이는 부분을 나누어 설명합니다. 전체 납입액을 모두 저축되는 금액으로 안내해서는 안 됩니다.","적립보험료에는 계약을 체결하고 관리하는 비용 등이 포함될 수 있습니다. 이러한 비용을 차감한 적립순보험료가 적립이율을 적용하는 기준이므로 공시된 이율을 전체 보험료에 그대로 적용하면 맞지 않습니다.","공시이율을 적용하는 구조에서는 이율이 바뀌면 이후 적립에 적용되는 조건도 달라질 수 있습니다. 최저보증이율이 있는 경우에도 이는 정해진 적립 부분에 대한 기준이지 납입보험료 전체의 수익 보장은 아닙니다.","적립 기능, 중도인출 가능 여부와 환급금 계산방식은 가입시기·상품에 따라 다릅니다. 적립보험료가 있다는 사실만으로 언제든 낸 돈을 그대로 찾을 수 있다고 설명하지 않습니다."],"practical":["총 보험료와 보장보험료, 적립보험료를 나누어 확인하고 실제 적립에 적용되는 비용과 이율을 설명합니다.","환급금 예시를 볼 때에는 적용이율과 중도인출 등 계산에 사용한 조건을 함께 확인합니다."],"faq":[],"path":"articles/refund/02/"},{"id":"maturity-0","cat":"basics","cat_name":"상품 기초개념","doc":"maturity","doc_name":"80세 만기와 100세 만기","index":0,"title":"만기 선택 기준","definition":"만기는 보험계약에서 정한 보장기간이 끝나는 시점이며 보험료 납입이 끝나는 시점과는 구분해야 합니다.","explanation":["보장기간은 일정 나이까지로 정하거나 계약일부터 일정 기간으로 정할 수 있습니다. 어떤 방식인지에 따라 종료 시점을 확인하는 방법이 달라지므로 만기 표시를 정확히 읽습니다.","보험료 납입기간은 보장기간과 다를 수 있습니다. 보험료를 모두 냈더라도 보장이 이어지는 계약이 있고 갱신형은 새로운 보험기간의 보험료 납입이 계속될 수 있습니다.","하나의 계약에서도 주계약과 특약의 만기가 서로 다를 수 있습니다. 가장 긴 보장기간만 보고 모든 담보가 같은 시점까지 유지된다고 설명하면 실제 계약과 차이가 생길 수 있습니다.","가입 가능한 나이와 선택할 수 있는 만기 및 납입기간은 가입시기·상품과 담보에 따라 다릅니다. 원하는 기간을 말로 정하는 것과 실제 청약에서 선택 가능한 기간을 구분해야 합니다."],"practical":["고객이 보장을 필요로 하는 기간과 실제 선택 가능한 만기를 대조하고 납입 종료 시점도 함께 표시합니다.","갱신형은 최초 만기와 갱신이 끝나는 최종 보장 시점을 구분하여 확인합니다.","담보별 종료 시점을 기록해 특정 보장이 먼저 끝나는 부분을 설명합니다."],"faq":[],"path":"articles/maturity/01/"},{"id":"nonrefund-0","cat":"basics","cat_name":"상품 기초개념","doc":"nonrefund","doc_name":"납입기간과 무해지상품","index":0,"title":"납입기간 설정","definition":"납입기간은 계약에서 보험료를 내기로 정한 기간으로 보장기간과 환급 조건을 함께 확인해야 하는 항목입니다.","explanation":["보장을 받는 기간과 보험료를 내는 기간은 같을 수도 있고 다를 수도 있습니다. 납입이 끝나면 계약도 끝난다는 뜻은 아니므로 보험기간과 나란히 확인합니다.","선택 가능한 납입기간은 가입나이, 담보와 상품 형태에 따라 달라집니다. 같은 보장 이름이라도 적용되는 납입조건을 실제 설계 내용에서 확인해야 합니다.","갱신형 특약은 주계약과 납입 구조가 다를 수 있습니다. 주계약 납입 종료 후에도 갱신형 특약 보험료가 남는지 확인하고, 계속 납입할 계약을 구분해 안내합니다.","환급금을 제한한 형태는 납입기간이 경과하기 전과 후의 해지 조건이 다를 수 있습니다. 납입면제가 되었다고 약정한 납입기간이 즉시 종료되는 것은 아니므로 환급금 산정 기준을 별도로 확인합니다."],"practical":["고객에게 납입 종료 시점, 보장 종료 시점, 갱신 후 납입 여부를 각각 설명합니다.","가입시기·상품에 따라 다른 납입기간 중 해지 조건을 확인하고 유지 가능한 납입계획인지 점검합니다.","납입면제와 납입기간 경과를 같은 의미로 설명하지 않습니다."],"faq":[],"path":"articles/nonrefund/01/"},{"id":"nonrefund-1","cat":"basics","cat_name":"상품 기초개념","doc":"nonrefund","doc_name":"납입기간과 무해지상품","index":1,"title":"무해지환급형 상품의 구조","definition":"무해지환급형은 정해진 기간에 해지하면 해약환급금을 지급하지 않는 조건을 반영한 보험 구조입니다.","explanation":["해약환급금이 있는 형태보다 낮은 보험료로 보장을 준비할 수 있도록 환급을 제한하는 구조가 있습니다. 보험료가 낮아진 이유를 설명할 때에는 해지 시 돌려받는 금액이 없을 수 있다는 조건도 함께 전달해야 합니다.","일정 기간이 지나면 환급금이 생기는 형태도 있지만 지급 수준이 다른 형태와 같다고 단정할 수 없습니다. 환급 제한 기간과 그 이후의 계산방식은 가입시기·상품에 따라 다릅니다.","납입면제 사유가 발생해 더 이상 보험료를 내지 않더라도 약정한 납입기간이 지나기 전에 해지하면 환급금이 없는 조건일 수 있습니다. 보험료 납입 의무와 해지환급금 조건을 나누어 봅니다.","만기환급금 유무와 중도해지 환급 제한은 별개입니다. 중도해지 시점별 금액을 확인하지 않은 채 나중에 낸 돈을 돌려받는 구조로 설명해서는 안 됩니다."],"practical":["납입기간 중과 경과 후의 해약환급금을 나누어 확인하고 환급 제한 구간을 명확하게 설명합니다.","가입 목적이 보장 유지인지 가까운 시기의 자금 마련인지 확인하여 중도해지 손실을 감당할 수 있는지 살핍니다."],"faq":[],"path":"articles/nonrefund/02/"},{"id":"disease-0","cat":"basics","cat_name":"상품 기초개념","doc":"disease","doc_name":"주요 질병과 인수기준","index":0,"title":"주요 질병의 원인 · 통계 · 치료법","definition":"보험 상담에서 질병을 이해한다는 것은 실제 진단과 치료 사실을 확인하여 고지와 보장조건을 구분하는 일입니다.","explanation":["질병명만으로 고지 내용이 모두 정리되는 것은 아닙니다. 진단 시점, 검사와 치료 내용, 입원·수술 여부 및 현재 상태를 구분해 확인해야 합니다.","청약 질문은 질병 자체와 의료행위를 서로 다르게 물을 수 있습니다. 치료가 끝났거나 현재 증상이 없다는 이유만으로 질문에 해당하지 않는다고 단정하지 않습니다.","질병의 원인이나 치료 방법을 설명하는 것과 보험 가입 가능성을 판단하는 것은 별개의 일입니다. 확인된 진료 사실을 바탕으로 해당 계약의 질문과 심사 절차를 따릅니다."],"practical":["고객의 표현을 임의의 진단명으로 바꾸지 말고 진료기록에 적힌 질병명과 의료행위를 확인합니다.","통계 수치나 치료 효과를 개인의 보장 필요성 또는 가입 가능성으로 바로 연결하지 않습니다."],"faq":[],"path":"articles/disease/01/"},{"id":"disease-1","cat":"basics","cat_name":"상품 기초개념","doc":"disease","doc_name":"주요 질병과 인수기준","index":1,"title":"질병별 인수기준","definition":"질병별 인수심사는 고지된 건강정보를 바탕으로 가입 가능 여부와 보장 조건을 결정하는 과정입니다.","explanation":["보험회사는 청약서에 적힌 사실을 바탕으로 위험을 평가합니다. 중요한 정보는 계약 거절뿐 아니라 가입금액 제한, 일부 보장 제외, 보험금 삭감이나 보험료 할증 등 조건부 인수 판단에도 영향을 줄 수 있습니다.","같은 질병명이라도 언제 진단받았는지, 어떤 치료를 받았는지, 현재 상태는 어떤지에 따라 확인할 정보가 달라집니다. 질병명 하나만으로 가입 여부를 확정해서 안내하지 않습니다.","일반심사와 간편심사는 질문 체계가 서로 다릅니다. 특정 질문에 해당하지 않는다고 하여 모든 담보가 자동으로 승인되는 것은 아니며 해당 상품과 특약의 추가 질문도 확인해야 합니다.","심사 기준은 가입시기·상품과 선택한 보장에 따라 다릅니다. 과거에 안내받은 결과나 다른 계약의 승인 이력을 현재 청약의 확정 결과로 사용해서는 안 됩니다."],"practical":["질병명, 진단·치료 시점, 치료방법, 재발 여부와 현재 상태를 구분해 회사가 요청한 방식으로 제출합니다.","조건부 승인이라면 제한되는 부위·질병·담보와 적용 내용을 고객이 이해했는지 확인합니다.","가입 심사 결과와 향후 보험금 지급 판단은 별개임을 설명합니다."],"faq":[],"path":"articles/disease/02/"},{"id":"ga-0","cat":"channel","cat_name":"판매채널·영업","doc":"ga","doc_name":"원수사와 GA","index":0,"title":"원수사","definition":"원수사는 고객의 보험계약을 인수하고 약정한 사고에 대해 보험금 지급 책임을 부담하는 보험회사입니다.","explanation":["보험을 설명하고 청약을 돕는 모집 담당자와 계약을 인수하는 보험회사는 역할이 다릅니다. 상담이 이루어졌다는 사실만으로 가입이 완료된 것은 아니므로 청약과 회사의 승낙 절차를 확인해야 합니다.","고객이 낸 답변과 서류는 계약 인수 판단에 사용됩니다. 설계사는 필요한 정보를 정확히 전달하고 고객이 보장내용과 중요한 조건을 이해하도록 돕지만 회사의 심사 결과를 임의로 바꿀 수는 없습니다.","보험사고가 발생하면 회사는 가입한 계약과 제출자료를 기준으로 지급 여부를 심사합니다. 담당 설계사의 예상 안내와 회사가 확정한 지급 결과는 구분하여 설명해야 합니다.","계약내용 변경 역시 요청을 전달하는 단계와 실제 변경이 반영되는 단계를 구분합니다. 추가 보험료나 효력 발생 조건이 있을 수 있으므로 변경을 요청했다는 이유만으로 보장이 바뀌었다고 단정하지 않습니다."],"practical":["고객에게 계약을 책임지는 회사와 상담·청약을 담당하는 소속 및 창구를 구분해 안내합니다.","가입이나 변경 후에는 처리 완료 내용과 실제 보장 개시 조건을 확인합니다."],"faq":[],"path":"articles/ga/01/"},{"id":"ga-1","cat":"channel","cat_name":"판매채널·영업","doc":"ga","doc_name":"원수사와 GA","index":1,"title":"대리점(GA): 연합형과 독립형","definition":"보험대리점은 보험회사의 위탁을 받아 보험계약 모집에 참여하는 판매 조직입니다.","explanation":["보험대리점을 통해 상담하거나 청약하더라도 보험계약을 인수하고 보험금 지급을 심사하는 주체는 해당 보험회사입니다. 판매조직의 명칭과 계약의 책임 주체를 구분해야 합니다.","대리점의 상담과 계약 변경 업무에서는 요청을 받는 것과 실제 계약에 반영되는 것이 다를 수 있습니다. 필요한 절차와 보험료 납입, 효력 발생 조건을 확인해야 합니다.","연합형이나 독립형이라는 표현만으로 조직의 권한, 지원 범위와 계약조건을 확정할 수 없습니다. 실제 소속 관계와 위탁 범위를 확인하고 고객 안내 창구를 명확히 정리합니다."],"practical":["고객에게 모집인의 소속, 계약을 인수하는 회사, 변경 및 청구를 접수할 창구를 나누어 안내합니다.","조직 형태만으로 인수심사나 보험금 지급이 유리하다고 설명하지 않습니다."],"faq":[],"path":"articles/ga/02/"},{"id":"ga-2","cat":"channel","cat_name":"판매채널·영업","doc":"ga","doc_name":"원수사와 GA","index":2,"title":"영업규정 · 수수료 · 근무환경","definition":"영업규정과 수수료 조건은 모집 업무의 범위와 보수 지급·반환 관계를 확인하는 기준입니다.","explanation":["모집수수료는 보험판매와 계약관리 등의 업무에 대해 지급하는 보수입니다. 수수료 안내에 예시가 있더라도 실제 지급조건과 같은지 확인해야 하며 조직이나 판매채널에 따라 달라질 수 있습니다.","수수료를 받았더라도 계약의 실효나 해지 등 약정한 사유가 발생하면 반환 문제가 생길 수 있습니다. 지급되는 금액만 보지 말고 반환 사유와 적용 규정도 함께 확인해야 합니다.","영업규정은 위촉관계에서 업무와 책임을 이해하는 데 필요합니다. 근무환경이나 지원 범위는 조직의 이름만으로 판단하지 말고 실제 계약과 안내 내용을 확인합니다."],"practical":["위촉 전에 보수의 산정·지급·반환 조건과 자신에게 적용되는 규정의 범위를 확인합니다.","설명이 다른 부분은 서면으로 정리하고, 내부 지급표나 영업자료를 고객용 안내에 그대로 사용하지 않습니다."],"faq":[],"path":"articles/ga/03/"},{"id":"offline-0","cat":"channel","cat_name":"판매채널·영업","doc":"offline","doc_name":"대면영업","index":0,"title":"지인 · DB · 브리핑 · 개척 · 법인영업","definition":"대면영업은 고객과 직접 만나 필요를 확인하고 보험계약의 내용을 설명하는 상담 방식입니다.","explanation":["지인 소개, 상담을 신청한 고객의 정보, 설명회나 현장 접촉 등 상담을 시작하는 경로는 다양합니다. 만남의 경로와 실제 고객이 보험상담에 동의한 범위는 구분해 확인해야 합니다.","고객정보를 전달받는 방식에서는 수집·이용 및 제공 동의가 어떤 내용으로 이루어졌는지 확인합니다. 연락처를 받았다는 사실만으로 모든 상담과 정보 이용이 허용된다고 단정하지 않습니다.","상담이 시작된 뒤에는 가입 목적에 맞는 내용 설명과 정확한 고지가 필요합니다. 고객과 친분이 있거나 여러 사람을 대상으로 설명했다는 이유로 개별 계약의 확인 절차가 생략되는 것은 아닙니다."],"practical":["상담 경로와 고객의 요청 내용을 먼저 확인하고 실제 계약자는 보장조건과 질문을 개별적으로 확인하도록 합니다.","법인을 대상으로 상담하더라도 계약자, 피보험자와 동의가 필요한 사람을 구분해 해당 절차를 확인합니다."],"faq":[],"path":"articles/offline/01/"},{"id":"offline-1","cat":"channel","cat_name":"판매채널·영업","doc":"offline","doc_name":"대면영업","index":1,"title":"재무설계: 수입/지출 · 상품관리","definition":"재무설계에서 보험을 검토하는 일은 수입과 지출을 파악하고 필요한 보장과 보험료 납입계획을 연결하는 과정입니다.","explanation":["수입과 생활비 등 지출은 같은 기간을 기준으로 정리해야 현재의 자금 흐름을 이해할 수 있습니다. 월 기준과 연 기준을 섞지 않고 고객이 확인한 금액으로 정리합니다.","보험료 지출을 살필 때에는 지금 내는 금액뿐 아니라 언제까지 내는지 확인합니다. 갱신형 담보는 이후 보험료가 변할 수 있으므로 현재 지출이 앞으로도 같다고 단정하지 않습니다.","보험의 환급금은 지급 시점과 조건이 정해져 있습니다. 만기환급금과 중도해지 환급금을 구분하고, 보장 목적으로 유지하는 계약을 즉시 사용할 수 있는 자금과 혼동하지 않습니다.","은퇴 등 장래 시점을 고려할 때에도 보장기간과 납입기간을 따로 확인합니다. 특정 비율을 모든 고객에게 일괄 적용하기보다 실제 수입·지출 정보와 계약조건을 함께 살펴야 합니다."],"practical":["수입·지출의 기준 기간과 확인 시점을 기록하고 보험료 납입 종료 시점을 함께 정리합니다.","가입시기·상품에 따라 다른 갱신 및 해지 조건을 확인한 뒤 유지 가능한 계획인지 고객과 점검합니다."],"faq":[],"path":"articles/offline/02/"},{"id":"offline-2","cat":"channel","cat_name":"판매채널·영업","doc":"offline","doc_name":"대면영업","index":2,"title":"금융기초: 은행 · 증권사 · 보험사","definition":"금융상품의 기초를 이해하려면 은행·증권사·보험사라는 기관 이름과 실제로 가입하는 상품의 성격을 구분해야 합니다.","explanation":["보험은 계약에서 정한 위험을 보장하거나 정해진 조건에 따라 금액을 지급하는 상품입니다. 저축 기능이 포함되어 있어도 은행의 예금·적금이나 펀드와 같은 상품으로 설명해서는 안 됩니다.","보험료에는 보장과 계약 관리 등에 필요한 비용이 반영됩니다. 적립이율은 정해진 비용 등을 차감한 금액에 적용될 수 있고, 중도해지 때에는 납입한 보험료보다 적은 금액을 받을 수 있습니다.","금융상품을 설명할 때에는 이름에 쓰인 저축이나 연금이라는 단어만 보지 말고 지급 조건, 유지기간과 중도해지 결과를 확인합니다. 구체적인 구조는 가입시기·상품에 따라 다릅니다."],"practical":["고객에게 실제 가입하는 상품이 보험인지부터 명확히 설명하고 예금처럼 납입액 전체가 그대로 쌓인다고 안내하지 않습니다.","환급금 예시의 적용이율과 비용, 지급 시점을 확인하여 보장 기능과 적립 기능을 구분합니다."],"faq":[],"path":"articles/offline/03/"},{"id":"offline-3","cat":"channel","cat_name":"판매채널·영업","doc":"offline","doc_name":"대면영업","index":3,"title":"정보받기 → 재무목표 설정 → 상품제안","definition":"정보 확인에서 상품제안으로 이어지는 상담은 고객의 목적을 파악하고 계약의 조건이 그 목적에 맞는지 확인하는 과정입니다.","explanation":["상담과 가입설계에 필요한 정보를 받을 때에는 이용 목적과 동의 내용을 확인합니다. 보험계약 상담에 필요한 동의와 상품소개 등 선택적인 마케팅 동의를 구분하여 설명합니다.","고객의 수입·지출 정보와 필요한 보장을 확인한 뒤 가입 목적을 정리합니다. 보험료를 내는 기간과 보장을 받는 기간, 중도해지 시 조건을 목적과 연결해 설명해야 합니다.","제안 단계에서는 보장내용과 중요한 제한 조건을 고객이 이해할 수 있도록 안내합니다. 제안에 동의한 것과 보험회사가 계약을 승낙한 것은 다른 단계이므로 심사와 청약 확인을 이어서 진행합니다.","고객이 질문에 사실대로 답하고 피보험자 동의 등 필요한 절차를 마쳤는지 확인해야 합니다. 상담 중 수집한 정보를 청약서에 반영할 때에는 최종 답변을 고객이 직접 확인하도록 합니다."],"practical":["받을 정보마다 상담 목적에 필요한 내용인지와 적용되는 동의 절차를 확인합니다.","고객이 원하는 목적, 제안한 보장, 남아 있는 제한 조건을 구분해 설명합니다.","제안 이후 청약과 승낙까지 처리된 내용을 확인하여 상담의 진행 상태를 명확히 안내합니다."],"faq":[],"path":"articles/offline/04/"},{"id":"online-0","cat":"channel","cat_name":"판매채널·영업","doc":"online","doc_name":"비대면영업","index":0,"title":"카페 · 댓글 · 광고 · SNS · 블로그","definition":"온라인 보험상담은 게시물과 광고 등으로 고객을 만나더라도 정보 이용과 계약 설명의 절차를 확인해야 하는 모집 방식입니다.","explanation":["카페나 블로그, 사회관계망서비스에서 일반적인 정보를 전달하는 것과 상담 신청을 받는 일은 구분해야 합니다. 연락처를 남기거나 상담을 요청하도록 연결하는 경우에는 광고 관련 검토와 정보 처리 절차를 확인합니다.","댓글이나 프로필에 연결한 상담 경로도 게시 내용과 함께 살펴야 합니다. 짧은 글이라는 이유만으로 상품 소개나 모집 활동에 대한 검토가 자동으로 생략되는 것은 아닙니다.","상담 신청 과정에서는 개인정보의 수집·이용과 다른 기관 제공 여부를 확인해야 합니다. 고객이 누구에게 어떤 목적으로 정보를 제공하는지 이해할 수 있도록 안내 내용을 구분합니다.","가입설계와 계약 상담에 필요한 동의와 선택적인 상품소개 동의는 같지 않을 수 있습니다. 고객이 요청한 범위와 실제 사용하는 정보를 확인하고 정해진 동의 절차를 따릅니다."],"practical":["본문뿐 아니라 댓글, 프로필과 상담 연결 부분을 함께 점검하여 게시 전 검토 범위를 확인합니다.","연락처를 수집하는 화면에서는 상담 제공자와 정보 이용 목적, 제공 관계를 고객이 확인할 수 있도록 합니다.","건강정보 등은 공개 댓글로 적도록 유도하지 말고 정해진 상담 및 동의 절차에서 확인합니다."],"faq":[],"path":"articles/online/01/"},{"id":"online-1","cat":"channel","cat_name":"판매채널·영업","doc":"online","doc_name":"비대면영업","index":1,"title":"블로그 포스팅 기본 양식과 상위노출 로직","definition":"보험 블로그 글은 독자가 내용을 이해하고 상담 여부를 판단할 수 있도록 사실과 조건을 분명하게 설명하는 안내 글입니다.","explanation":["공개 글에 보험 관련 내용을 담을 때에는 일반 설명과 실제 가입 조건을 구분합니다. 상품마다 다른 지급조건을 생략한 채 누구나 같은 보장을 받는다는 인상을 주지 않도록 점검합니다.","상담 연락처나 연결 경로를 포함하면 정보성 글이라고 이름 붙였더라도 광고 검토가 필요할 수 있습니다. 본문뿐 아니라 프로필과 댓글에 붙인 상담 연결도 함께 확인합니다.","글의 형식이나 게시 방식만으로 검색 상위노출을 보장하는 기준은 이 안내에서 제시하지 않습니다. 공개 게시에서는 정확한 설명과 필요한 광고 검토를 우선 확인합니다."],"practical":["제목에 약속한 내용과 본문이 일치하는지 확인하고 보장 설명에는 적용 조건과 예외를 함께 씁니다.","게시 전 상담 연결을 포함한 전체 내용을 검토하고, 게시 후 내용이 바뀌면 다시 확인합니다."],"faq":[],"path":"articles/online/02/"},{"id":"online-2","cat":"channel","cat_name":"판매채널·영업","doc":"online","doc_name":"비대면영업","index":2,"title":"블로그 컨셉 잡기와 로열키워드","definition":"보험 블로그의 주제와 검색어는 독자가 어떤 정보를 찾는지에 맞추어 설명의 범위를 정하는 요소입니다.","explanation":["보장내용이나 계약 절차를 주제로 정했다면 해당 내용을 실제 계약조건과 구분해 설명해야 합니다. 특정 검색어를 넣었다는 이유로 가입 가능성이나 지급 결과를 확정해서 안내할 수는 없습니다.","상담을 유도하는 제목과 게시물은 광고 관련 검토가 필요한지 확인합니다. 본문을 일반 정보로 작성했더라도 연락처나 상담 연결이 포함되는지 함께 살펴야 합니다.","특정 키워드가 상담이나 계약을 보장한다는 기준은 확인되지 않았습니다. 검색어 선택과 보험 설명의 정확성은 별개의 검토 사항으로 다룹니다."],"practical":["게시물을 공개하기 전에 제목과 검색어가 실제 본문 내용을 과장하지 않는지 확인합니다.","게시물의 목적과 상담 연결 여부를 명확히 하고 필요한 광고 검토를 거칩니다."],"faq":[],"path":"articles/online/03/"},{"id":"online-3","cat":"channel","cat_name":"판매채널·영업","doc":"online","doc_name":"비대면영업","index":3,"title":"검색량 · 포스팅 수 · 제한키워드 · 노출기준 확인","definition":"온라인 게시 전 점검은 검색 지표를 보는 일과 게시 내용의 광고·개인정보 조건을 확인하는 일을 구분하는 과정입니다.","explanation":["검색량이나 게시물 수를 확인하더라도 그 수치만으로 상담이나 보험계약의 성과를 확정할 수는 없습니다. 특정 수치나 비율을 상위노출의 공식으로 제시하지 않습니다.","게시 가능 여부와 광고 검토 여부는 별도로 확인해야 합니다. 보험상담 연락처와 상담 연결을 넣은 글이나 댓글은 전체 내용을 기준으로 검토가 필요한지 살펴봅니다.","고객정보를 받는 경로에서는 어떤 기관이 정보를 수집하고 어디에 제공하는지 확인합니다. 검색 노출을 위한 게시물 점검과 개인정보 동의 점검을 서로 대신할 수는 없습니다."],"practical":["검색 지표가 높다는 이유로 내용의 적정성이나 광고 검토가 끝났다고 보지 않습니다.","상담 신청 화면과 연결 경로를 포함하여 정보 수집·이용 및 제공 동의가 필요한 부분을 확인합니다."],"faq":[],"path":"articles/online/04/"},{"id":"online-4","cat":"channel","cat_name":"판매채널·영업","doc":"online","doc_name":"비대면영업","index":4,"title":"유튜브 · 네이버TV · SNS 마케팅","definition":"보험 영상과 사회관계망서비스 게시물은 시청자에게 전달되는 설명과 상담 연결을 함께 점검해야 하는 공개 콘텐츠입니다.","explanation":["영상이나 짧은 게시물에서도 보험에 관한 설명은 실제 보장과 중요한 조건을 정확히 전달해야 합니다. 화면이나 설명란에 상담 연락처와 연결 경로가 있다면 광고 관련 검토가 필요한지 함께 확인합니다.","플랫폼이나 게시 형식이 달라져도 보험상담을 유도하는 내용인지 살펴야 합니다. 본문뿐 아니라 댓글과 프로필에 포함한 연결도 확인 범위에 들어갈 수 있습니다.","시청자가 상담을 신청할 때에는 개인정보 수집·이용과 제공 관계를 안내하고 필요한 동의를 확인합니다. 게시물을 본 사실이나 반응을 남긴 사실을 상담정보 제공 동의와 혼동하지 않습니다.","콘텐츠에서 개별 가입 가능성이나 지급 결과를 확정하지 않습니다. 상담으로 이어진 경우에는 고객의 사실관계와 해당 계약조건을 확인하는 절차를 진행합니다."],"practical":["영상 내용과 설명란, 프로필, 댓글에 적은 상담 안내를 함께 검토합니다.","상담 신청 단계에서 제공자와 이용 목적을 알 수 있도록 하고 실제 동의한 범위에 맞추어 정보를 받습니다."],"faq":[],"path":"articles/online/05/"}],"base":"/wiki-preview/"};
